/// Immutable dependencies supplied by the source-asset caller for one form.
/// Form-local indexes deliberately remain inside the parser.
pub(super) struct FormParseContext<'a> {
    type_index: &'a BTreeMap<String, String>,
    type_index_collisions: &'a BTreeSet<String>,
    dcs_type_index: &'a DcsTypeIndex,
    object_refs: &'a BTreeMap<String, String>,
    /// The declared type of every metadata field, shared rather than copied:
    /// it is configuration-wide, while a parse context is per form.
    field_type_refs: &'a Arc<BTreeMap<String, String>>,
    information_register_field_refs: &'a InformationRegisterFieldReferenceIndex,
    /// Master dimensions in declaration order, shared for the same reason as
    /// `field_type_refs`: configuration-wide against a per-form context.
    information_register_master_dimensions: &'a Arc<InformationRegisterMasterDimensionIndex>,
    form_owner_reference: Option<&'a str>,
    /// Object references overlaid with the form index, for the one property
    /// that names a form: `<ChoiceForm>`. The plain object reference index the
    /// rest of the parser uses does not resolve form identifiers to their
    /// owning object, so a form named through it comes out under the wrong
    /// owner; the caller passes the index that does.
    form_reference_index: Option<&'a BTreeMap<String, String>>,
    /// The same per-object index the standalone `Ext/CommandInterface.xml`
    /// reader uses, threaded here so the form's own embedded
    /// `<CommandInterface>` can decline a `.StandardCommand.X` name when the
    /// target declares `UseStandardCommands=false` -- see
    /// `MetadataCommandReference::use_standard_commands`. `None` (the default)
    /// behaves as an empty index: every target resolves as before.
    metadata_command_refs: Option<&'a BTreeMap<String, MetadataCommandReference>>,
    dcs_source_profile: ProfileId,
    dcs_target_profile: ProfileId,
    trace_sink: Option<&'a dyn FormItemTraceSink>,
}

pub(crate) trait FormItemTraceSink {
    fn record(&self, event: FormItemTraceEvent);
    fn record_schema(&self, _event: FormItemSchemaTraceEvent) {}
}

#[derive(Debug, Clone, Eq, PartialEq, serde::Serialize)]
pub(crate) struct FormItemTraceEvent {
    pub(crate) id: String,
    pub(crate) tag: String,
    pub(crate) name: String,
    pub(crate) occurrence: usize,
    pub(crate) wrapper: String,
    pub(crate) raw_field_count: usize,
    pub(crate) normalized_field_count: usize,
    pub(crate) owner_chain: Vec<String>,
    pub(crate) top_level_scalars: Vec<FormItemTraceScalar>,
}

#[derive(Debug, Clone, Eq, PartialEq, serde::Serialize)]
pub(crate) struct FormItemTraceScalar {
    pub(crate) index: usize,
    pub(crate) value: Option<String>,
    pub(crate) nested: bool,
}

impl<'a> FormParseContext<'a> {
    #[allow(clippy::too_many_arguments)]
    pub(super) fn new(
        type_index: &'a BTreeMap<String, String>,
        type_index_collisions: &'a BTreeSet<String>,
        dcs_type_index: &'a DcsTypeIndex,
        object_refs: &'a BTreeMap<String, String>,
        field_type_refs: &'a Arc<BTreeMap<String, String>>,
        information_register_field_refs: &'a InformationRegisterFieldReferenceIndex,
        information_register_master_dimensions: &'a Arc<InformationRegisterMasterDimensionIndex>,
        form_owner_reference: Option<&'a str>,
    ) -> Self {
        Self {
            type_index,
            type_index_collisions,
            dcs_type_index,
            object_refs,
            field_type_refs,
            information_register_field_refs,
            information_register_master_dimensions,
            form_owner_reference,
            form_reference_index: None,
            metadata_command_refs: None,
            dcs_source_profile: ProfileId::parse("provider:mssql-legacy")
                .expect("static MSSQL provider profile is valid"),
            dcs_target_profile: ProfileId::parse("xml-2.20").expect("static XML profile is valid"),
            trace_sink: None,
        }
    }

    pub(super) fn with_form_reference_index(
        mut self,
        form_reference_index: &'a BTreeMap<String, String>,
    ) -> Self {
        self.form_reference_index = Some(form_reference_index);
        self
    }

    pub(super) fn with_metadata_command_refs(
        mut self,
        metadata_command_refs: &'a BTreeMap<String, MetadataCommandReference>,
    ) -> Self {
        self.metadata_command_refs = Some(metadata_command_refs);
        self
    }

    pub(super) fn with_dcs_profiles(
        mut self,
        source_profile: ProfileId,
        target_profile: ProfileId,
    ) -> Self {
        self.dcs_source_profile = source_profile;
        self.dcs_target_profile = target_profile;
        self
    }

    #[allow(dead_code)]
    pub(super) fn with_trace_sink(mut self, trace_sink: &'a dyn FormItemTraceSink) -> Self {
        self.trace_sink = Some(trace_sink);
        self
    }
}

#[allow(dead_code)]
pub(crate) fn extract_form_body_xml(
    bytes: &[u8],
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let body = crate::compiler::bodies::form::decode_compatible_managed_form(bytes).ok()?;
    extract_form_body_xml_from_body(body.parsed(), object_refs, object_refs)
}

pub(super) fn extract_form_body_xml_from_body(
    body: &ParsedFormBodyBlob,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    extract_form_body_xml_from_body_timed(
        body,
        &FormParseContext::new(
            type_index,
            &BTreeSet::new(),
            &DcsTypeIndex::new(),
            object_refs,
            &Arc::new(BTreeMap::new()),
            &BTreeMap::new(),
            &Arc::new(InformationRegisterMasterDimensionIndex::new()),
            None,
        ),
        None,
    )
}

pub(super) fn extract_form_body_xml_from_body_timed(
    body: &ParsedFormBodyBlob,
    context: &FormParseContext<'_>,
    timings: Option<&mut MssqlDumpTimingReport>,
) -> Option<String> {
    match extract_form_body_xml_from_body_detailed_timed(body, context, timings)? {
        DetailedFormBodyExtraction::Emitted { xml, .. } => Some(xml),
        DetailedFormBodyExtraction::OpaqueNotEmitted { .. }
        | DetailedFormBodyExtraction::Rejected { .. } => None,
    }
}

#[derive(Debug, Clone, Eq, PartialEq)]
pub(super) struct FormSourceAssetDiagnostic {
    pub(super) code: &'static str,
    pub(super) classification: &'static str,
    pub(super) parse_error_class: Option<&'static str>,
    pub(super) property: &'static str,
    pub(super) property_profile: &'static str,
    pub(super) property_slot: usize,
    pub(super) form_item_id: String,
    pub(super) form_item_tag: &'static str,
    pub(super) raw_length: usize,
    pub(super) raw_sha256: String,
}

pub(super) enum DetailedFormBodyExtraction {
    Emitted {
        xml: String,
        diagnostics: Vec<FormSourceAssetDiagnostic>,
    },
    OpaqueNotEmitted {
        diagnostics: Vec<FormSourceAssetDiagnostic>,
    },
    Rejected {
        diagnostics: Vec<FormSourceAssetDiagnostic>,
        error: FormSchemaWriteError,
    },
}

pub(super) fn extract_form_body_xml_from_body_detailed_timed(
    body: &ParsedFormBodyBlob,
    context: &FormParseContext<'_>,
    mut timings: Option<&mut MssqlDumpTimingReport>,
) -> Option<DetailedFormBodyExtraction> {
    let started = Instant::now();
    let form_fields = split_1c_braced_fields(&body.layout, 0)?;
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_split_cpu_ms += elapsed_ms(started);
    }

    let started = Instant::now();
    let mut properties = extract_form_body_properties(&form_fields, context.form_owner_reference);
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_properties_cpu_ms += elapsed_ms(started);
    }

    let started = Instant::now();
    let events = extract_form_body_events(&form_fields);
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_events_cpu_ms += elapsed_ms(started);
    }

    let started = Instant::now();
    let mut attributes = extract_form_body_attributes_with_dcs_type_index(
        &body.trailing,
        context.type_index,
        context.dcs_type_index,
        context.object_refs,
    );
    let attribute_save_field_bindings = extract_form_body_attribute_save_field_bindings(
        &body.trailing,
        context.type_index,
        context.object_refs,
    );
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_attributes_cpu_ms += elapsed_ms(started);
    }
    let attributes_section =
        extract_form_body_attributes_section(&body.trailing, context.object_refs);

    let started = Instant::now();
    properties.report_result = extract_form_report_attribute_ref(&form_fields, "5", &attributes);
    properties.details_data = extract_form_report_attribute_ref(&form_fields, "6", &attributes);
    properties.variant_appearance = FormRootVariantAppearanceSchema::from_raw_layout(
        form_fields.first().map(|field| field.trim()),
    )
    .and_then(|_| {
        extract_form_report_attribute_ref(
            &form_fields,
            FormRootVariantAppearanceSchema::PROPERTY_BAG_KEY,
            &attributes,
        )
    });
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_properties_cpu_ms += elapsed_ms(started);
    }

    let started = Instant::now();
    let parameters = extract_form_body_parameters(&body.trailing, context.type_index);
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_parameters_cpu_ms += elapsed_ms(started);
    }

    let started = Instant::now();
    let mut child_item_indexes = collect_form_child_item_indexes_with_object_refs(
        &form_fields,
        &attributes,
        context.object_refs,
        context.trace_sink,
    );
    properties.mobile_device_command_bar_content = extract_form_mobile_device_command_bar_content(
        &form_fields,
        &child_item_indexes.item_name_by_id,
    );
    properties.custom_settings_folder =
        extract_form_custom_settings_folder(&form_fields, &child_item_indexes.item_name_by_id);
    let child_item_indexes_cpu_ms = elapsed_ms(started);

    let started = Instant::now();
    let commands = extract_form_body_commands(
        &body.trailing,
        context.object_refs,
        &child_item_indexes.item_name_by_id,
    );
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_commands_cpu_ms += elapsed_ms(started);
    }

    let started = Instant::now();
    // The command bar's own buttons address the form's attributes exactly as
    // any other item does, so they are read against the same name index rather
    // than against an empty one: UT 11.5.27.75
    // `Catalogs/ВариантыОтчетов/Forms/ФормаЭлемента`, Button `ФормаОткрыть`
    // carries `{2,{1},{-8}}` against attribute 1 `Объект` and the platform
    // writes `<DataPath>Объект.Ref</DataPath>`.
    let auto_command_bar_attribute_names = attributes
        .iter()
        .map(|attribute| (attribute.id.clone(), attribute.name.clone()))
        .collect::<BTreeMap<_, _>>();
    let auto_command_bar = extract_form_auto_command_bar(
        &form_fields,
        &commands,
        context.object_refs,
        &auto_command_bar_attribute_names,
        // Same reason the names are shared: the command bar's buttons address
        // the form's attributes exactly as any other item does, and a button
        // whose slot names a standard attribute of the attribute's own type
        // cannot be spelled without the attribute's type. Evidence: UT
        // 11.5.27.75 `ExchangePlans/ОбменССайтом/Forms/ФормаУзла`, whose three
        // command-bar buttons carry `{2,{1},{-6}}` and are written
        // `<DataPath>Объект.Ref</DataPath>`.
        &form_attribute_metadata_owners_by_id(&attributes),
        &child_item_indexes.table_name_by_id,
        &child_item_indexes.standard_command_owner_name_by_id,
        &child_item_indexes.command_source_owner_name_by_id,
        // The command bar's buttons address the form's tables exactly as any
        // other item does, so they are read against the same column and
        // type-link indexes rather than against empty ones: over all 355 such
        // slots in UT 11.5.27.75 the shared route agrees with the platform
        // outright, and 21 of them are named only once the indexes are present.
        &child_item_indexes.table_column_names_by_id,
        &child_item_indexes.type_link_data_path_by_table_column,
    );
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_auto_command_bar_cpu_ms += elapsed_ms(started);
    }

    let started = Instant::now();
    apply_form_body_attribute_additional_columns(
        &mut attributes,
        &body.trailing,
        context.type_index,
        context.object_refs,
        &child_item_indexes,
    );
    extend_form_choice_parameter_link_table_current_data_routes_from_additional_columns(
        &mut child_item_indexes,
        &attributes,
    );
    collect_form_chain_walk_member_indexes(
        &mut child_item_indexes,
        &attributes,
        Arc::clone(context.field_type_refs),
    );
    collect_form_item_rooted_chain_roots(&mut child_item_indexes, &attributes, context.object_refs);
    apply_form_attribute_save_field_bindings(
        &mut attributes,
        &attribute_save_field_bindings,
        &child_item_indexes.data_path_by_binding_key,
        context.object_refs,
    );
    let mut child_items = extract_form_child_items(
        &form_fields,
        &attributes,
        &commands,
        context.type_index,
        context.type_index_collisions,
        context.object_refs,
        &child_item_indexes,
        context.trace_sink,
    );
    resolve_form_choice_form_references(
        &mut child_items,
        context.form_reference_index.unwrap_or(context.object_refs),
    );
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_child_items_cpu_ms +=
            child_item_indexes_cpu_ms + elapsed_ms(started);
    }

    let started = Instant::now();
    let command_interface = extract_form_command_interface_with_context(
        &body.trailing,
        &commands,
        context.object_refs,
        context.information_register_field_refs,
        context.information_register_master_dimensions,
        context.form_owner_reference,
        &attributes,
        &child_item_indexes,
        context.metadata_command_refs,
    );
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_command_interface_cpu_ms += elapsed_ms(started);
    }

    let mut diagnostics = Vec::new();
    collect_opaque_choice_list_diagnostics(&child_items, &mut diagnostics);
    if let Some(auto_command_bar) = auto_command_bar.as_ref() {
        collect_opaque_choice_list_diagnostics(&auto_command_bar.child_items, &mut diagnostics);
    }
    let has_opaque_choice_list = !diagnostics.is_empty();
    collect_opaque_choice_parameters_diagnostics(&child_items, &mut diagnostics);
    if let Some(auto_command_bar) = auto_command_bar.as_ref() {
        collect_opaque_choice_parameters_diagnostics(
            &auto_command_bar.child_items,
            &mut diagnostics,
        );
    }
    diagnostics.sort_by(|left, right| {
        (
            left.form_item_id.as_str(),
            left.form_item_tag,
            left.property,
            left.property_profile,
            left.property_slot,
            left.code,
            left.raw_sha256.as_str(),
        )
            .cmp(&(
                right.form_item_id.as_str(),
                right.form_item_tag,
                right.property,
                right.property_profile,
                right.property_slot,
                right.code,
                right.raw_sha256.as_str(),
            ))
    });

    if has_opaque_choice_list {
        // Writer-corpus, policy, and other formatter failures are never diagnostic data
        // failures. Exercise every fallible writer path before taking the one recoverable exit;
        // emitted forms continue through the real formatter exactly once below.
        if let Err(error) = preflight_form_writer_paths_with_dcs_profiles(
            &child_items,
            auto_command_bar
                .as_ref()
                .map(|command_bar| command_bar.child_items.as_slice()),
            &attributes,
            &attributes_section,
            &context.dcs_source_profile,
            &context.dcs_target_profile,
        ) {
            return Some(DetailedFormBodyExtraction::Rejected { diagnostics, error });
        }
        return Some(DetailedFormBodyExtraction::OpaqueNotEmitted { diagnostics });
    }

    // With no opaque ChoiceList left, the existing typed preflight remains an invariant check
    // immediately before formatting.
    if let Err(error) = validate_form_choice_list_writer_trees(
        &child_items,
        auto_command_bar
            .as_ref()
            .map(|command_bar| command_bar.child_items.as_slice()),
    ) {
        return Some(DetailedFormBodyExtraction::Rejected { diagnostics, error });
    }

    let started = Instant::now();
    let xml = match format_form_body_xml_with_dcs_profiles(
        &properties,
        auto_command_bar.as_ref(),
        &events,
        &child_items,
        &attributes,
        &attributes_section,
        &parameters,
        &commands,
        &command_interface,
        &context.dcs_source_profile,
        &context.dcs_target_profile,
    ) {
        Ok(xml) => xml,
        Err(error) => {
            return Some(DetailedFormBodyExtraction::Rejected { diagnostics, error });
        }
    };
    if let Some(timings) = timings.as_deref_mut() {
        timings.source_asset_form_format_cpu_ms += elapsed_ms(started);
    }
    Some(DetailedFormBodyExtraction::Emitted { xml, diagnostics })
}

pub(super) fn collect_opaque_choice_list_diagnostics(
    items: &[FormChildItem],
    diagnostics: &mut Vec<FormSourceAssetDiagnostic>,
) {
    for item in items {
        if let CanonicalFormChoiceList::OpaqueSameProfile { raw, provenance } = &item.choice_list {
            let opaque_diagnostic = provenance.layout.opaque_diagnostic(raw);
            let identity = opaque_diagnostic.identity();
            diagnostics.push(FormSourceAssetDiagnostic {
                code: identity.code(),
                classification: identity.classification(),
                parse_error_class: None,
                property: identity.property(),
                property_profile: identity.profile(),
                property_slot: provenance.slot,
                form_item_id: item.id.clone(),
                form_item_tag: item.tag,
                raw_length: opaque_diagnostic.raw_length(),
                raw_sha256: opaque_diagnostic.raw_sha256().to_owned(),
            });
        }
        collect_opaque_choice_list_diagnostics(&item.child_items, diagnostics);
    }
}

pub(super) fn collect_opaque_choice_parameters_diagnostics(
    items: &[FormChildItem],
    diagnostics: &mut Vec<FormSourceAssetDiagnostic>,
) {
    for item in items {
        if let Some(cluster) = &item.choice_parameter_cluster {
            if let FormChoiceParameterLinks::Opaque(value) = cluster.links() {
                let mut raw_hasher = Sha256::new();
                let mut raw_length = 0usize;
                for raw in [&value.primary_raw, &value.duplicate_raw]
                    .into_iter()
                    .flatten()
                {
                    raw_hasher.update(raw.as_bytes());
                    raw_length += raw.len();
                }
                diagnostics.push(FormSourceAssetDiagnostic {
                    code: "source_asset.form.choice_parameter_links.opaque_rejected",
                    classification: "opaque_property_rejected",
                    parse_error_class: Some(form_choice_parameter_links_parse_error_class(
                        &value.error,
                    )),
                    property: "ChoiceParameterLinks",
                    property_profile: "input_field_extended_options_mirrored",
                    property_slot: value.primary_slot,
                    form_item_id: item.id.clone(),
                    form_item_tag: item.tag,
                    raw_length,
                    raw_sha256: format!("{:x}", raw_hasher.finalize()),
                });
            }
            if let CanonicalFormChoiceParameters::OpaqueSameProfile { raw, slot } =
                cluster.parameters()
            {
                diagnostics.push(FormSourceAssetDiagnostic {
                    code: "source_asset.form.choice_parameters.opaque_omitted",
                    classification: "opaque_property_omitted",
                    parse_error_class: None,
                    property: "ChoiceParameters",
                    property_profile: "input_field_extended_options",
                    property_slot: *slot,
                    form_item_id: item.id.clone(),
                    form_item_tag: item.tag,
                    raw_length: raw.len(),
                    raw_sha256: format!("{:x}", Sha256::digest(raw.as_bytes())),
                });
            }
            if let FormChoiceParameterAvailableTypes::Opaque(value) = cluster.available_types() {
                diagnostics.push(FormSourceAssetDiagnostic {
                    code: "source_asset.form.available_types.opaque_omitted",
                    classification: "opaque_property_omitted",
                    parse_error_class: None,
                    property: "AvailableTypes",
                    property_profile: "input_field_extended_options",
                    property_slot: value.slot,
                    form_item_id: item.id.clone(),
                    form_item_tag: item.tag,
                    raw_length: value.raw.len(),
                    raw_sha256: format!("{:x}", Sha256::digest(value.raw.as_bytes())),
                });
            }
        }
        collect_opaque_choice_parameters_diagnostics(&item.child_items, diagnostics);
    }
}

fn form_choice_parameter_links_parse_error_class(
    error: &FormChoiceParameterLinksParseError,
) -> &'static str {
    match error {
        FormChoiceParameterLinksParseError::PrimaryMalformed => "primary_malformed",
        FormChoiceParameterLinksParseError::DuplicateMalformed => "duplicate_malformed",
        FormChoiceParameterLinksParseError::MirrorMismatch => "mirror_mismatch",
        FormChoiceParameterLinksParseError::UnresolvedAttribute(_) => "unresolved_attribute",
    }
}

