pub(super) fn extract_form_dimension(fields: &[&str], index: usize) -> Option<String> {
    let value = fields.get(index)?.trim();
    if value == "0" || value.parse::<u32>().is_err() {
        return None;
    }
    Some(value.to_string())
}

pub(super) fn extract_form_window_opening_mode(fields: &[&str]) -> Option<&'static str> {
    match fields.get(2).map(|field| field.trim())? {
        "0" => None,
        "1" => Some("LockOwnerWindow"),
        "2" => Some("LockWholeInterface"),
        _ => None,
    }
}

pub(super) fn extract_form_enter_key_behavior(fields: &[&str]) -> Option<&'static str> {
    match fields.get(5).map(|field| field.trim())? {
        "0" => Some("DefaultButton"),
        _ => None,
    }
}

/// `SaveWindowSettings` sits in the trailer's own *last* slot -- offset 23 of
/// the classic 24-member trailer, but genuinely the last slot rather than a
/// coincidence: forms carrying a built-in Navigator/quick-search child item
/// write one extra field ahead of the same 24-shape (see
/// `form_root_child_items_tail_start_50_with_navigator_gap`'s doc comment),
/// and this property's value is unaffected -- it is still the very last
/// field, now at relative offset 24 instead of 23. Reading `trailer.len() -
/// 1` rather than a fixed `+23` makes both trailer shapes resolve to the
/// same field. Evidence: ERP УХ 3.2.12.6,
/// `Catalogs/КартыИсследованияТоваров/Forms/ФормаСписка` (25-member trailer,
/// Navigator item present, last trailer field `"0"`, native writes
/// `<SaveWindowSettings>false</SaveWindowSettings>`) -- the strict `[24]`
/// search found no valid count-list at all and silently dropped the
/// property, identical in shape to the `MobileDeviceCommandBarContent` gap
/// this same form's trailer also carries (that form's own content tuple
/// happens to declare zero items here, so it produced no separate diff).
pub(super) fn extract_form_save_window_settings(fields: &[&str]) -> Option<bool> {
    let tail_start = form_root_trailer_start(fields)?;
    let blocks = form_root_trailer_optional_blocks(
        fields.first().map(|field| field.trim()),
        fields.get(tail_start..)?,
    )?;
    match fields
        .get(tail_start + 23 + blocks)
        .map(|field| field.trim())?
    {
        "0" => Some(false),
        _ => None,
    }
}

pub(super) fn extract_form_auto_title(fields: &[&str]) -> Option<bool> {
    match fields.get(9).map(|field| field.trim())? {
        "0" => Some(false),
        _ => None,
    }
}

pub(super) fn extract_form_auto_url(fields: &[&str]) -> Option<bool> {
    let root_discriminator = fields.first().map(|field| field.trim());
    match root_discriminator {
        Some("49") | Some("50") => {
            let tail_start = form_root_trailer_start(fields)?;
            FormRootAutoUrlSchema::from_raw_layout(root_discriminator, fields.get(tail_start..)?)?
                .auto_url()
        }
        Some("59") => FormRootAutoUrlSchema::from_legacy_raw_layout(
            root_discriminator,
            fields,
            form_root_uses_property_bag(fields),
        )?
        .auto_url(),
        _ => None,
    }
}

pub(super) fn extract_form_save_data_in_settings(fields: &[&str]) -> Option<&'static str> {
    // Root field 6 reads `1` for every one of the 89 attributable UT roots whose
    // native document carries `<SaveDataInSettings>UseList</...>` and `0` for
    // the other 4 986, whatever the property bag holds - the bag is not a
    // second reader of this property, so gating on it only suppressed the 2
    // roots that carry both. The legacy `59` layout keeps the old gate, having
    // no observation of its own.
    if fields.first().map(|field| field.trim()) != Some("50") && form_root_uses_property_bag(fields)
    {
        return None;
    }
    match fields.get(6).map(|field| field.trim())? {
        "1" => Some("UseList"),
        _ => None,
    }
}

pub(super) fn extract_form_auto_save_data_in_settings(fields: &[&str]) -> Option<&'static str> {
    match fields.get(7).map(|field| field.trim())? {
        "1" => Some("Use"),
        _ => None,
    }
}

pub(super) fn extract_form_root_group(fields: &[&str]) -> Option<&'static str> {
    let root_discriminator = fields.first().map(|field| field.trim());
    match root_discriminator {
        Some("49") | Some("50") => {
            let tail_start = form_root_trailer_start(fields)?;
            FormRootGroupSchema::from_raw_layout(
                root_discriminator,
                fields.get(11).copied(),
                fields.get(tail_start..)?,
            )?
            .group()
        }
        Some("59") => {
            FormRootGroupSchema::from_legacy_raw_layout(root_discriminator, fields)?.group()
        }
        _ => None,
    }
}

pub(super) fn extract_form_command_set_excluded_commands(
    fields: &[&str],
    form_owner_reference: Option<&str>,
) -> Vec<&'static str> {
    let property_bag_command_set = fields
        .get(18)
        .and_then(|value| value.trim().parse::<usize>().ok())
        .and_then(|property_count| {
            property_count
                .checked_mul(2)
                .and_then(|offset| 20usize.checked_add(offset))
        })
        .and_then(|command_slot| fields.get(command_slot))
        .and_then(|field| parse_form_table_counted_uuid_list(field));
    let command_set = if let Some(command_set) = property_bag_command_set {
        command_set
    } else {
        if fields.len() != 22
            || fields.get(18).map(|field| field.trim()) != Some("{0}")
            || !form_table_child_owner_section_starts_at(fields, 20)
        {
            return Vec::new();
        }
        let Some(command_set) = fields
            .get(19)
            .and_then(|field| parse_form_table_counted_uuid_list(field))
        else {
            return Vec::new();
        };
        command_set
    };
    let business_process_or_task = form_owner_reference.is_some_and(|owner| {
        matches!(
            owner.split_once('.').map(|(kind, _)| kind),
            Some("BusinessProcess" | "Task")
        )
    });
    let mut commands = map_known_form_excluded_commands(&command_set, |uuid| {
        form_standard_excluded_command_name(uuid, business_process_or_task)
            .or_else(|| form_root_table_excluded_command_name(uuid))
            // The older excluded-command table predates several root form
            // standard commands.  The canonical command name is available
            // from the shared Form.StandardCommand table, so retain its
            // suffix rather than handling individual UUIDs here.
            .or_else(|| form_standard_command_name(uuid)?.strip_prefix("Form.StandardCommand."))
    });
    extend_joint_form_excluded_commands(
        &mut commands,
        &command_set,
        &[
            "441362c1-0c86-4f73-bf50-6e1048a2db73",
            "4c569466-1af5-4fc1-9b63-7bf6493097bf",
        ],
        &["Post", "UndoPosting"],
    );
    commands
}

fn form_root_table_excluded_command_name(uuid: &str) -> Option<&'static str> {
    match uuid {
        // These table command UUIDs are evidenced in root Form/CommandSet lists.
        "8969c93a-23e5-4bef-941d-aaef315858d2"
        | "daa306cd-a78a-4e74-a14c-739daba624cb"
        | "d8e20c4d-3519-49aa-80e5-d6d66fee741a" => form_table_standard_command_suffix(uuid),
        _ => None,
    }
}

