fn form_document_field_geometry_options<'a>(
    tag: &str,
    fields: &[&'a str],
) -> Option<(&'static FormDocumentFieldGeometry, Vec<&'a str>)> {
    let layout = FORM_DOCUMENT_FIELD_GEOMETRY
        .iter()
        .find_map(|(candidate, layout)| (*candidate == tag).then_some(layout))?;
    let options = split_1c_braced_fields(fields.get(39)?.trim(), 0)?;
    (options.first()?.trim() == layout.discriminator && options.len() == layout.len)
        .then_some((layout, options))
}

/// `None` for every document-field kind that has no such slot, and for the
/// slot's own default -- which is exactly what the platform leaves unwritten.
fn parse_form_document_field_extent(
    tag: &str,
    fields: &[&str],
    pick: fn(&FormDocumentFieldGeometry) -> Option<(usize, &'static str)>,
) -> Option<String> {
    let (layout, options) = form_document_field_geometry_options(tag, fields)?;
    let (slot, default) = pick(layout)?;
    options
        .get(slot)
        .map(|field| field.trim())
        .filter(|value| *value != default && *value != "0" && value.parse::<u32>().is_ok())
        .map(str::to_string)
}

fn parse_form_document_field_max_extent(
    tag: &str,
    fields: &[&str],
    pick: fn(&FormDocumentFieldGeometry) -> Option<usize>,
) -> Option<String> {
    let (layout, options) = form_document_field_geometry_options(tag, fields)?;
    let slot = pick(layout)?;
    options
        .get(slot)
        .map(|field| field.trim())
        .filter(|value| *value != "0" && value.parse::<u32>().is_ok())
        .map(str::to_string)
}

fn parse_form_document_field_font_xml(
    tag: &str,
    fields: &[&str],
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let (layout, options) = form_document_field_geometry_options(tag, fields)?;
    parse_form_font_tuple_xml(options.get(layout.font?)?, object_refs)
}

/// The auto-max and stretch flags all default to `1`, which the platform
/// leaves unwritten; only the `0` state reaches the XML.
fn parse_form_document_field_flag(
    tag: &str,
    fields: &[&str],
    pick: fn(&FormDocumentFieldGeometry) -> Option<usize>,
) -> Option<bool> {
    let (layout, options) = form_document_field_geometry_options(tag, fields)?;
    let slot = pick(layout)?;
    match options.get(slot).map(|field| field.trim()) {
        Some("0") => Some(false),
        _ => None,
    }
}

/// Reads a grouping item's `<Width>`/`<Height>`; `0` means the platform writes
/// no element.
pub(super) fn parse_form_group_extent(tag: &str, fields: &[&str], slot: usize) -> Option<String> {
    if !form_group_layout_tag(tag) {
        return None;
    }
    fields
        .get(slot)
        .map(|field| field.trim())
        .filter(|value| *value != "0" && value.parse::<u32>().is_ok())
        .map(str::to_string)
}

/// Reads a grouping item's `<HorizontalStretch>`/`<VerticalStretch>`; the `2`
/// state means "unset" and is the one the platform leaves unwritten.
pub(super) fn parse_form_group_stretch(tag: &str, fields: &[&str], slot: usize) -> Option<bool> {
    if !form_group_layout_tag(tag) {
        return None;
    }
    match fields.get(slot).map(|field| field.trim()) {
        Some("0") => Some(false),
        Some("1") => Some(true),
        _ => None,
    }
}

pub(super) fn parse_form_usual_group_title_font_xml(
    fields: &[&str],
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let raw = fields.get(FORM_GROUP_TITLE_FONT_SLOT)?.trim();
    let font = split_1c_braced_fields(raw, 0)?;
    // A leading `8` is the same tuple under the wider group layout.
    let normalized = (font.first()?.trim() == "8").then(|| {
        let mut normalized = font.clone();
        normalized[0] = "7";
        format!("{{{}}}", normalized.join(","))
    });
    parse_form_title_font_tuple_xml(normalized.as_deref().unwrap_or(raw), object_refs)
}

pub(super) fn parse_form_usual_group_extended_options(
    fields: &[&str],
) -> Option<FormUsualGroupExtendedOptions> {
    let options =
        split_1c_braced_fields(fields.get(FormUsualGroupSchema::OPTIONS_SLOT)?.trim(), 0)?;
    match options.first()?.trim() {
        "29" => {
            let schema = FormUsualGroupSchema::from_raw_layout(
                fields.first()?.trim(),
                fields.len(),
                "UsualGroup",
                fields.get(5).map(|field| field.trim()),
                &options,
            )?;
            let properties = schema.properties(fields, &options);
            Some(FormUsualGroupExtendedOptions {
                group: parse_form_usual_group_property_bag_group(&options),
                behavior: parse_form_usual_group_property_bag_behavior(&options),
                representation: parse_form_usual_group_property_bag_representation(&options),
                horizontal_stretch: parse_form_usual_group_horizontal_stretch(fields),
                enabled: properties.enabled(),
                read_only: properties.read_only(),
                height: schema.height(fields),
                shortcut: schema
                    .shortcut_field(fields)
                    .and_then(|field| parse_common_command_shortcut_value(field)),
                enable_content_change: properties.enable_content_change(),
                group_horizontal_align: properties.group_horizontal_align(),
                group_vertical_align: properties.group_vertical_align(),
                children_align: properties.children_align(),
                horizontal_spacing: properties.horizontal_spacing(),
                vertical_spacing: properties.vertical_spacing(),
                child_items_width: properties.child_items_width(),
                control_representation: properties.control_representation(),
                collapsed: properties.collapsed(),
                collapsed_representation_title: schema
                    .collapsed_representation_title_field(&options)
                    .map(parse_form_localized_strings)
                    .unwrap_or_default(),
                horizontal_align: properties.horizontal_align(),
                vertical_align: properties.vertical_align(),
                format: schema
                    .format_field(&options)
                    .map(parse_form_localized_strings)
                    .unwrap_or_default(),
                through_align: properties.through_align(),
                united: properties.united(),
                show_left_margin: properties.show_left_margin(),
            })
        }
        // The compact/legacy 28-member option bag: one member shorter than
        // the wide `29`-bag, but `Group` and `ShowTitle` sit at the exact
        // same relative slots as they do there (1/27 and 4), which is
        // exactly what a `29`-bag with one *later* member removed would
        // look like from the front.
        //
        // Evidence, five native records across two independent
        // configurations (ERP UH `MDM_Management.cf`, three items, and the
        // ERP UH main `1cv8.cf`, two items found by an exhaustive scan of
        // every `UsualGroup` in the 140 411-file native export tree whose
        // `Group`/`Behavior`/`ShowTitle` we currently get wrong):
        //
        // - `Group`: slot 1 `"0"` with slot 27 not `"1"`/`"3"`/`"4"` writes
        //   `Vertical` (`MDM_Management`
        //   `Catalogs/ТипыБазДанных/Forms/ФормаЭлемента` item
        //   `ГруппаНастройкиПодключения`, and
        //   `InformationRegisters/.../ФормаСписка` item
        //   `СписокКомпоновщикНастроекПользовательскиеНастройки`); slot 1
        //   `"1"` with slot 27 not in that set writes nothing (`ГруппаОбменДаннымиКонтроляНСИ`
        //   in the same form as the first); slot 27 `"1"` writes `Horizontal`
        //   regardless of slot 1 (`1cv8.cf`
        //   `Catalogs/БланкиОтчетов/Forms/ВыборДействияВолшебнойПалочки`
        //   item `Группа1`, slot 1 `"1"`, slot 27 `"1"`) -- the exact rule
        //   `parse_form_usual_group_property_bag_group` already proved for
        //   the `29`-bag, reused verbatim rather than re-derived.
        // - `ShowTitle`: slot 4 `"0"` writes `false` (`Группа1` above, and
        //   `СписокКомпоновщикНастроекПользовательскиеНастройки`); slot 4
        //   `"1"` writes nothing (the other three) -- wired through
        //   `FormChildItemShowTitleSchema`, not this struct, at the same
        //   slot 4 the `29`-bag already uses.
        // - `Behavior`: `Usual` on four of the five records, slots 10, 12 and
        //   24 all `"0"`; `Collapsible` on the fifth (`1cv8.cf`
        //   `Documents/НастраиваемыйОтчет/Forms/ФормаИзмененияПоказателейНО`
        //   item `ГруппаАналитики`, also natively `<Collapsed>true</Collapsed>`),
        //   all three slots `"1"`. No record disagreeing between the three
        //   slots, and no record of `PopUp`, has been found in either
        //   configuration; `parse_form_usual_group_compact_bag_behavior`
        //   requires the three slots to agree and declines outright rather
        //   than guess at the value a disagreement or an unobserved code
        //   would mean.
        // - `Representation`: slot 3, read through the bag-wide
        //   `parse_form_usual_group_property_bag_representation`, whose
        //   evidence covers this revision.
        "28" => Some(FormUsualGroupExtendedOptions {
            group: parse_form_usual_group_property_bag_group(&options),
            behavior: parse_form_usual_group_compact_bag_behavior(&options),
            representation: parse_form_usual_group_property_bag_representation(&options),
            horizontal_stretch: None,
            enabled: None,
            read_only: None,
            height: None,
            shortcut: None,
            enable_content_change: None,
            group_horizontal_align: None,
            group_vertical_align: None,
            children_align: None,
            horizontal_spacing: None,
            vertical_spacing: None,
            child_items_width: None,
            control_representation: None,
            collapsed: None,
            collapsed_representation_title: Vec::new(),
            horizontal_align: None,
            vertical_align: None,
            format: Vec::new(),
            through_align: None,
            united: None,
            show_left_margin: None,
        }),
        "38" => {
            let group = parse_form_extended_group(
                options.get(1)?.trim(),
                options.get(22).map(|value| value.trim()),
                options.get(27).map(|value| value.trim()),
                options.get(36).map(|value| value.trim()),
            );
            let representation = parse_form_usual_group_property_bag_representation(&options);
            let behavior = parse_form_extended_group_behavior(
                fields.get(16).map(|value| value.trim()),
                fields.get(17).map(|value| value.trim()),
                options.get(10).map(|value| value.trim()),
                options.get(11).map(|value| value.trim()),
                options.get(24).map(|value| value.trim()),
                options.get(28).map(|value| value.trim()),
            );
            Some(FormUsualGroupExtendedOptions {
                group,
                behavior,
                representation,
                horizontal_stretch: None,
                enabled: None,
                read_only: None,
                height: None,
                shortcut: None,
                enable_content_change: None,
                group_horizontal_align: None,
                group_vertical_align: None,
                children_align: None,
                horizontal_spacing: None,
                vertical_spacing: None,
                child_items_width: None,
                control_representation: None,
                collapsed: None,
                collapsed_representation_title: Vec::new(),
                horizontal_align: None,
                vertical_align: None,
                format: Vec::new(),
                through_align: None,
                united: None,
                show_left_margin: None,
            })
        }
        _ => None,
    }
}

/// `Representation` of a grouping control, read off its property bag.
///
/// Slot 3 under the code table `parse_form_child_item_representation` states,
/// shared by every bag revision rather than restated once per arm.
///
/// Evidence for the compact `28` revision, which used to leave the slot
/// unread: every `28` bag in ERP УХ 3.2.12.6 -- 916 bags in 392 forms, 912 of
/// which name exactly one item in the native tree, all 912 of them
/// `UsualGroup` -- carries at slot 3 a value that is a function of the element
/// the platform writes on that item, with no bag disagreeing: `0` ->
/// `<Representation>None</Representation>` (581 bags), `2` -> no element at
/// all (300, `WeakSeparation` being the `UsualGroup` default that
/// `form_child_item_representation_is_default` suppresses), `3` ->
/// `NormalSeparation` (23) and `1` -> `StrongSeparation` (12).  Leaving the
/// slot unread lost `<Representation>` on 137 ERP УХ forms.
pub(super) fn parse_form_usual_group_property_bag_representation(
    options: &[&str],
) -> Option<&'static str> {
    options
        .get(3)
        .and_then(|field| parse_form_child_item_representation(field))
}

pub(super) fn parse_form_usual_group_property_bag_group(options: &[&str]) -> Option<&'static str> {
    match options.get(27).map(|value| value.trim()) {
        Some("1") => Some("Horizontal"),
        Some("3") => Some("AlwaysHorizontal"),
        Some("4") => Some("HorizontalIfPossible"),
        _ => match options.get(1).map(|value| value.trim()) {
            Some("0") => Some("Vertical"),
            _ => None,
        },
    }
}

pub(super) fn parse_form_usual_group_property_bag_behavior(
    options: &[&str],
) -> Option<&'static str> {
    match options.get(28).map(|value| value.trim())? {
        "0" => Some("Usual"),
        "1" => Some("Collapsible"),
        "2" => Some("PopUp"),
        "3" => None,
        _ => None,
    }
}

/// `Behavior` of a compact-bag (`28`) `UsualGroup`. Unlike the wide `29`-bag,
/// which carries it at one dedicated slot, every native record this reader
/// has seen echoes the same code at two slots -- 10 and 24 -- rather than
/// one: five records read `"0","0"` and write `<Behavior>Usual</Behavior>`
/// explicitly (this bag never leaves it unwritten, unlike the wide `29`-bag's
/// default-omits-`Usual` convention), and one reads `"1","1"` and writes
/// `<Behavior>Collapsible</Behavior>`. None has shown `PopUp` (code `2` on
/// the wide bag) at all, in either configuration this was checked against.
///
/// A third slot, 12, sits between them and echoes the *same* two values on
/// six of these seven records, which first read as a triple-redundant
/// `Behavior`; the seventh disproves that (ERP UH `1cv8.cf`
/// `Documents/ЗаявкиНаЛьготныйКредит/Forms/ФормаДокумента` item
/// `ГруппаРеквизитовОрганизации`: slots 10/24 both `"0"`, `Behavior=Usual`
/// natively, but slot 12 is `"1"`) -- natively this same record also carries
/// `<CollapsedRepresentationTitle>` and `<Collapsed>true</Collapsed>`, so
/// slot 12 is that `Collapsed` flag (storable, and stored, independently of
/// `Behavior`), not a third echo. Requiring slots 10 and 24 to agree is a
/// validity check the reader gets for free from having two copies rather
/// than one; a record where they disagree, or where they agree on a code
/// besides `0`/`1`, declines rather than guesses, exactly as an
/// unrecognised option-bag discriminator already does one level up.
pub(super) fn parse_form_usual_group_compact_bag_behavior(
    options: &[&str],
) -> Option<&'static str> {
    let value = options.get(10).map(|value| value.trim())?;
    if options.get(24).map(|field| field.trim()) != Some(value) {
        return None;
    }
    match value {
        "0" => Some("Usual"),
        "1" => Some("Collapsible"),
        _ => None,
    }
}

pub(super) fn parse_form_usual_group_horizontal_stretch(fields: &[&str]) -> Option<bool> {
    match fields.get(14).map(|value| value.trim())? {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

pub(super) fn parse_form_usual_group_width(fields: &[&str]) -> Option<String> {
    let value = fields.get(12)?.trim();
    (value != "0" && value.parse::<u32>().is_ok()).then(|| value.to_string())
}

pub(super) fn parse_form_usual_group_vertical_stretch(fields: &[&str]) -> Option<bool> {
    match fields.get(15).map(|value| value.trim())? {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

pub(super) fn parse_form_extended_group(
    orientation: &str,
    group_code: Option<&str>,
    layout_code: Option<&str>,
    mirror_code: Option<&str>,
) -> Option<&'static str> {
    match (orientation, group_code, layout_code, mirror_code) {
        ("0", Some("0"), Some("0"), Some("0")) => Some("Vertical"),
        ("1", Some("1"), Some("1"), Some("1")) => Some("Horizontal"),
        ("1", Some("1"), Some("3"), Some("3")) => Some("AlwaysHorizontal"),
        ("1", Some("2"), Some("2"), Some("2")) => Some("HorizontalIfPossible"),
        _ => None,
    }
}

pub(super) fn parse_form_child_item_representation(field: &str) -> Option<&'static str> {
    match field.trim() {
        "0" => Some("None"),
        "1" => Some("StrongSeparation"),
        "2" => Some("WeakSeparation"),
        "3" => Some("NormalSeparation"),
        _ => None,
    }
}

pub(super) fn parse_form_extended_group_behavior(
    style_field: Option<&str>,
    size_field: Option<&str>,
    flag10: Option<&str>,
    flag11: Option<&str>,
    flag24: Option<&str>,
    flag28: Option<&str>,
) -> Option<&'static str> {
    if style_field.is_some_and(|field| field.starts_with("{4,3"))
        && size_field.is_some_and(|field| field.starts_with("{8,2"))
        && flag10 == Some("1")
        && flag11 == Some("0")
        && flag24 == Some("2")
        && flag28 == Some("2")
    {
        return Some("PopUp");
    }
    if flag10 == Some("1") && flag11 == Some("1") && flag24 == Some("1") && flag28 == Some("1") {
        return Some("Collapsible");
    }
    if flag10 == Some("0") && flag11 == Some("0") && flag24 == Some("0") && flag28 == Some("0") {
        return Some("Usual");
    }
    None
}

pub(super) fn parse_form_child_item_group(field: &str) -> Option<&'static str> {
    match field.trim() {
        "0" => Some("Vertical"),
        "1" => Some("Horizontal"),
        "2" => Some("AlwaysHorizontal"),
        "3" => Some("HorizontalIfPossible"),
        "4" => Some("InCell"),
        _ => None,
    }
}

pub(super) fn parse_form_column_group_group(field: &str) -> Option<&'static str> {
    match field.trim() {
        "0" => Some("Horizontal"),
        "2" => Some("InCell"),
        _ => None,
    }
}

pub(super) fn parse_form_child_item_show_title(field: &str) -> Option<bool> {
    match field.trim() {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

/// `HeaderHorizontalAlign` of a table column control.
///
/// The code sits in its own top-level slot right after `HorizontalAlign`
/// (`23 + offset`). Over every `InputField` (46 850), `LabelField` (28 558) and
/// `PictureField` (2 126) item of the 5 021 attributable native forms the map
/// `1 -> Center`, `2 -> Right`, `3 -> Auto`, `0 -> nothing written` holds with no
/// counter-example, and no other code occurs.
pub(super) fn parse_form_field_header_horizontal_align(
    fields: &[&str],
    top_level_offset: usize,
) -> Option<&'static str> {
    if !form_input_field_layout_is_extended(fields) {
        return None;
    }
    match fields.get(24 + top_level_offset)?.trim() {
        "1" => Some("Center"),
        "2" => Some("Right"),
        "3" => Some("Auto"),
        _ => None,
    }
}

/// `HeaderHorizontalAlign` of a `ColumnGroup` lives in member 4 of the option
/// tuple, and uses the alignment codes the platform reuses for group alignment:
/// `0 -> Left`, `1 -> Center`, `2 -> Right`, `3` being the default it omits.
/// Confirmed on all 5 654 `ColumnGroup` items with no counter-example.
pub(super) fn parse_form_column_group_header_horizontal_align(
    options: &[&str],
) -> Option<&'static str> {
    match options.get(4)?.trim() {
        "0" => Some("Left"),
        "1" => Some("Center"),
        "2" => Some("Right"),
        _ => None,
    }
}

/// `Enabled` of container, decoration and table-addition items.
///
/// Each kind carries the flag in a plain top-level slot; `0` writes
/// `<Enabled>false</Enabled>` and `1` writes nothing. No other code occurs on the
/// 11 308 `LabelDecoration`, 3 601 `PictureDecoration`, 6 668 `Page`, 4 638
/// `SearchStringAddition`, 4 492 `SearchControlAddition` and 4 410
/// `ViewStatusAddition` items of the attributable native forms.
pub(super) fn parse_form_container_enabled(tag: &str, fields: &[&str]) -> Option<bool> {
    let slot = match tag {
        "LabelDecoration" | "PictureDecoration" => 9,
        // `ColumnGroup` and `Pages` carry the flag in the same container slot as
        // `Page`, and were the only two grouping kinds the table left out: over
        // the native UT 11.5.27.75 tree slot 10 reads `0` on exactly the 4 of
        // 6 016 `ColumnGroup` items and the 1 of 2 684 `Pages` items that carry
        // `<Enabled>false</Enabled>` and `1` on every other one, with no other
        // code on either kind.
        "Page"
        | "Pages"
        | "ColumnGroup"
        | "SearchStringAddition"
        | "SearchControlAddition"
        | "ViewStatusAddition" => 10,
        _ => return None,
    };
    (fields.get(slot)?.trim() == "0").then_some(false)
}

/// `MarkNegatives` is a tri-state option member: `1` writes `true`, `2` writes
/// nothing. It never carries any other code.
pub(super) fn parse_form_option_mark_negatives(options: &[&str], slot: usize) -> Option<bool> {
    (options.get(slot)?.trim() == "1").then_some(true)
}

/// `HeaderHeight` of a `Table` is the plain top-level slot 27; `1` is the default
/// the platform omits. Confirmed on all 4 410 `Table` items.
pub(super) fn parse_form_table_header_height(fields: &[&str]) -> Option<String> {
    let value = fields.get(27)?.trim();
    (value != "1" && value.parse::<u32>().is_ok()).then(|| value.to_owned())
}

pub(super) fn parse_form_child_item_show_in_header(fields: &[&str]) -> Option<bool> {
    let index = 20 + form_input_field_top_level_offset(fields);
    match fields.get(index).map(|field| field.trim())? {
        "0" => Some(false),
        _ => None,
    }
}

pub(super) fn form_button_layout_is_extended(fields: &[&str]) -> bool {
    fields.len() > 20
}

pub(super) fn form_button_top_level_offset(fields: &[&str]) -> usize {
    fields
        .get(5)
        .and_then(|field| parse_1c_quoted_string_with_len(field.trim()))
        .filter(|(value, _)| !value.is_empty())
        .map(|_| 0)
        .unwrap_or(1)
}

pub(super) fn form_input_field_layout_is_extended(fields: &[&str]) -> bool {
    fields.len() > 20
}

pub(super) fn form_input_field_extended_options<'a>(fields: &'a [&'a str]) -> Option<Vec<&'a str>> {
    fields.iter().skip(39).find_map(|field| {
        let options = split_1c_braced_fields(field.trim(), 0)?;
        let options = normalize_form_property_bag_revision(&options).unwrap_or(options);
        matches!(options.first().map(|field| field.trim()), Some("36" | "38")).then_some(options)
    })
}

pub(super) fn parse_form_radio_button_options<'a>(fields: &'a [&'a str]) -> Option<Vec<&'a str>> {
    fields.iter().skip(39).find_map(|field| {
        let options = split_1c_braced_fields(field.trim(), 0)?;
        (options.first().map(|value| value.trim()) == Some("8")).then_some(options)
    })
}

pub(super) fn form_input_field_top_level_offset(fields: &[&str]) -> usize {
    fields
        .get(6)
        .and_then(|field| parse_1c_quoted_string_with_len(field.trim()))
        .filter(|(value, _)| !value.is_empty())
        .map(|_| 0)
        .unwrap_or(1)
}

fn parse_exact_1c_quoted_string(field: &str) -> Option<String> {
    let field = field.trim();
    let (value, consumed) = parse_1c_quoted_string_with_len(field)?;
    (consumed == field.len()).then_some(value)
}

#[cfg(test)]
pub(super) fn parse_form_input_field_choice_parameter_links(
    primary: &str,
    duplicate: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
) -> Result<Vec<ibcmd_schema::FormChoiceParameterLink>, FormChoiceParameterLinksParseError> {
    parse_schema_form_choice_parameter_links(primary, duplicate, |attribute_id| {
        attribute_names_by_id.get(attribute_id).cloned()
    })
}

/// The member name a standard choice-parameter-link terminal reaches.
///
/// A marker names a *position* in the standard-attribute list of the type the
/// attribute is declared as, not a fixed member: `-5` is `Owner` on a catalog
/// object and `Ref` on a document object. The bound-field chain walk already
/// reads it that way against one family-scoped table per generated owner type,
/// and this is the same physical marker in the same role, so it is read against
/// the same table here instead of a second, family-blind one.
///
/// Evidence: UT 11.5.27.75. The configuration spells out 88 such terminals.
/// Where the attribute declares exactly one type and that type's table names
/// the marker, the table's name is the one the platform writes -- the six
/// `cfg:DocumentObject`/`-5` links of `Documents/План*` all write
/// `Объект.Ref`, which the family-blind reading spelled `Объект.Owner`, and the
/// six `cfg:CatalogObject`/`-5` links of `Catalogs/*` all write `Объект.Owner`,
/// as do the `cfg:DocumentObject`/`-3` links with `Объект.Date`. Two terminals
/// name a marker their own table does not list
/// (`cfg:CatalogRef.ДоговорыЭквайринга`/`-8`) or sit on an attribute with no
/// single declared type (`DataProcessor.НастройкиВнутреннегоЭДО`, `-8`); both
/// write `Ref`, which is what those three markers were historically spelled as,
/// so that spelling is kept as the reading of last resort rather than turned
/// into a rejection of two files the export already writes correctly.
///
/// Outside those three markers there is no last resort: a marker whose family
/// table does not name it has no spelling this code is entitled to invent, so
/// the link is refused and the caller keeps the whole collection opaque. The
/// four `cfg:ChartOfCharacteristicTypesObject`/`-2` terminals are the only ones
/// the corpus puts through that door, and the table now names them.
fn form_choice_parameter_link_standard_terminal_member(
    attribute_id: &str,
    standard: FormChoiceParameterLinkStandardTerminal,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
) -> Option<&'static str> {
    let marker = standard.marker_text();
    attribute_metadata_owners_by_id
        .get(attribute_id)
        .and_then(|owner| owner.exact_single_type_reference.as_deref())
        .and_then(|reference| form_standard_attribute_name_for_type_reference(reference, &marker))
        .or_else(|| match standard.marker() {
            -3 => Some("Date"),
            -5 => Some("Owner"),
            -8 => Some("Ref"),
            _ => None,
        })
}

pub(super) fn parse_form_input_field_choice_parameter_links_with_metadata(
    primary: &str,
    duplicate: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    data_path_by_binding_key: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Result<Vec<ibcmd_schema::FormChoiceParameterLink>, FormChoiceParameterLinksParseError> {
    parse_schema_form_choice_parameter_links_with_reference_resolver(
        primary,
        duplicate,
        |reference| match reference {
            FormChoiceParameterLinkReference::FormAttribute {
                attribute_id,
                terminal,
            } => match terminal {
                FormChoiceParameterLinkTerminal::Absent => {
                    attribute_names_by_id.get(attribute_id).cloned()
                }
                FormChoiceParameterLinkTerminal::Standard(standard) => {
                    let member = form_choice_parameter_link_standard_terminal_member(
                        attribute_id,
                        *standard,
                        attribute_metadata_owners_by_id,
                    )?;
                    attribute_names_by_id
                        .get(attribute_id)
                        .map(|attribute| format!("{attribute}.{member}"))
                }
                FormChoiceParameterLinkTerminal::MetadataUuid(uuid) => {
                    match resolve_form_owner_scoped_metadata_uuid_data_path_status(
                        attribute_id,
                        "0",
                        uuid,
                        attribute_metadata_owners_by_id,
                        object_refs,
                    ) {
                        FormMetadataDataPathResolution::Resolved(data_path) => Some(data_path),
                        FormMetadataDataPathResolution::NotMetadata
                        | FormMetadataDataPathResolution::ReferenceAbsent
                        | FormMetadataDataPathResolution::Invalid
                        | FormMetadataDataPathResolution::ForeignOwner => None,
                    }
                }
            },
            FormChoiceParameterLinkReference::TableCurrentData { table_id, terminal } => {
                let table_id = table_id.to_string();
                match terminal {
                    FormChoiceParameterLinkTableCurrentDataTerminal::BindingId(column_id) => {
                        let column_id = column_id.to_string();
                        type_link_data_path_by_table_column
                            .get(&(table_id.clone(), column_id.clone()))
                            .cloned()
                            .or_else(|| {
                                resolve_form_item_current_data_path(
                                    &table_id,
                                    &column_id,
                                    table_name_by_id,
                                    table_column_names_by_id,
                                    data_path_by_binding_key,
                                )
                            })
                    }
                    FormChoiceParameterLinkTableCurrentDataTerminal::MetadataUuid(uuid) => {
                        type_link_data_path_by_table_column
                            .get(&(table_id.clone(), format!("0|{uuid}")))
                            .cloned()
                            .or_else(|| {
                                resolve_form_table_current_data_metadata_uuid_path(
                                    &table_id,
                                    uuid,
                                    table_name_by_id,
                                    object_refs,
                                )
                            })
                    }
                    FormChoiceParameterLinkTableCurrentDataTerminal::BindingUuid {
                        binding_id,
                        uuid,
                    } => {
                        let binding_id = binding_id.to_string();
                        let uuid_route = type_link_data_path_by_table_column
                            .get(&(table_id.clone(), format!("{binding_id}|{uuid}")))
                            .cloned();
                        let numeric_route = type_link_data_path_by_table_column
                            .get(&(table_id.clone(), binding_id.clone()))
                            .cloned()
                            .or_else(|| {
                                resolve_form_item_current_data_path(
                                    &table_id,
                                    &binding_id,
                                    table_name_by_id,
                                    table_column_names_by_id,
                                    data_path_by_binding_key,
                                )
                            });
                        // The UUID here is the fixed value-table-column binding
                        // marker, so `{column_id, marker}` addresses the very
                        // column `{column_id}` alone addresses: the two keys are
                        // one reference written two ways, not two references.
                        // The route table is keyed by both spellings, but only
                        // the bare numeric key carries the route the layout
                        // states outright; the `id|uuid` key is filled in by the
                        // supplemental `AdditionalColumns` representation, whose
                        // documented precedence is *below* the layout route.
                        // Requiring the supplemental key and condemning a
                        // disagreement inverted that precedence, so 17 links
                        // whose layout route the platform writes were rejected
                        // in favour of an `AdditionalColumns` name the platform
                        // never writes there.
                        numeric_route.or(uuid_route)
                    }
                }
            }
        },
    )
}

#[cfg(test)]
pub(super) fn canonical_form_input_field_choice_parameter_links(
    schema: FormFieldSchema,
    options: &[&str],
    attribute_names_by_id: &BTreeMap<String, String>,
) -> CanonicalFormChoiceParameterLinks {
    let primary_slot = InputFieldSlot::ChoiceParameterLinks.index();
    let duplicate_slot = InputFieldSlot::ChoiceParameterLinksDuplicate.index();
    let primary = schema.input_field_option(options, InputFieldSlot::ChoiceParameterLinks);
    let duplicate =
        schema.input_field_option(options, InputFieldSlot::ChoiceParameterLinksDuplicate);
    // A member the record's own revision does not carry is *absent*, not
    // malformed: the short `32`/62 revision of the `InputField` option tuple
    // ends four members before the `5007` mirror this reader cross-checks
    // against, so the collection cannot be read here at all.  Reporting it
    // malformed instead made the writer refuse the whole form.
    if options.get(primary_slot) == Some(&FORM_ITEM_ABSENT_MEMBER)
        || options.get(duplicate_slot) == Some(&FORM_ITEM_ABSENT_MEMBER)
    {
        return FormChoiceParameterLinks::Absent;
    }
    let (Some(primary), Some(duplicate)) = (primary, duplicate) else {
        return FormChoiceParameterLinks::Opaque(OpaqueFormChoiceParameterLinksValue {
            primary_raw: primary.map(str::to_owned),
            duplicate_raw: duplicate.map(str::to_owned),
            primary_slot,
            duplicate_slot,
            error: if primary.is_none() {
                FormChoiceParameterLinksParseError::PrimaryMalformed
            } else {
                FormChoiceParameterLinksParseError::DuplicateMalformed
            },
        });
    };
    match parse_form_input_field_choice_parameter_links(primary, duplicate, attribute_names_by_id) {
        Ok(links) if links.is_empty() => FormChoiceParameterLinks::Empty,
        Ok(links) => FormChoiceParameterLinks::Typed(links),
        Err(error) => FormChoiceParameterLinks::Opaque(OpaqueFormChoiceParameterLinksValue {
            primary_raw: Some(primary.to_owned()),
            duplicate_raw: Some(duplicate.to_owned()),
            primary_slot,
            duplicate_slot,
            error,
        }),
    }
}

pub(super) fn canonical_form_input_field_choice_parameter_links_with_metadata(
    schema: FormFieldSchema,
    options: &[&str],
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    data_path_by_binding_key: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> CanonicalFormChoiceParameterLinks {
    let primary_slot = InputFieldSlot::ChoiceParameterLinks.index();
    let duplicate_slot = InputFieldSlot::ChoiceParameterLinksDuplicate.index();
    let primary = schema.input_field_option(options, InputFieldSlot::ChoiceParameterLinks);
    let duplicate =
        schema.input_field_option(options, InputFieldSlot::ChoiceParameterLinksDuplicate);
    // A member the record's own revision does not carry is *absent*, not
    // malformed: the short `32`/62 revision of the `InputField` option tuple
    // ends four members before the `5007` mirror this reader cross-checks
    // against, so the collection cannot be read here at all.  Reporting it
    // malformed instead made the writer refuse the whole form.
    if options.get(primary_slot) == Some(&FORM_ITEM_ABSENT_MEMBER)
        || options.get(duplicate_slot) == Some(&FORM_ITEM_ABSENT_MEMBER)
    {
        return FormChoiceParameterLinks::Absent;
    }
    let (Some(primary), Some(duplicate)) = (primary, duplicate) else {
        return FormChoiceParameterLinks::Opaque(OpaqueFormChoiceParameterLinksValue {
            primary_raw: primary.map(str::to_owned),
            duplicate_raw: duplicate.map(str::to_owned),
            primary_slot,
            duplicate_slot,
            error: if primary.is_none() {
                FormChoiceParameterLinksParseError::PrimaryMalformed
            } else {
                FormChoiceParameterLinksParseError::DuplicateMalformed
            },
        });
    };
    match parse_form_input_field_choice_parameter_links_with_metadata(
        primary,
        duplicate,
        attribute_names_by_id,
        attribute_metadata_owners_by_id,
        table_name_by_id,
        table_column_names_by_id,
        type_link_data_path_by_table_column,
        data_path_by_binding_key,
        object_refs,
    ) {
        Ok(links) if links.is_empty() => FormChoiceParameterLinks::Empty,
        Ok(links) => FormChoiceParameterLinks::Typed(links),
        Err(error) => FormChoiceParameterLinks::Opaque(OpaqueFormChoiceParameterLinksValue {
            primary_raw: Some(primary.to_owned()),
            duplicate_raw: Some(duplicate.to_owned()),
            primary_slot,
            duplicate_slot,
            error,
        }),
    }
}

pub(super) fn canonical_form_input_field_choice_parameters(
    schema: FormFieldSchema,
    options: &[&str],
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
    object_refs: &BTreeMap<String, String>,
) -> CanonicalFormChoiceParameters {
    let slot = InputFieldSlot::ChoiceParameters.index();
    let Some(raw) = schema.input_field_option(options, InputFieldSlot::ChoiceParameters) else {
        return CanonicalFormChoiceParameters::Absent;
    };
    match parse_form_input_field_choice_parameters(
        raw,
        type_index,
        type_index_collisions,
        object_refs,
    ) {
        Some(parameters) if parameters.is_empty() => CanonicalFormChoiceParameters::Empty { slot },
        Some(parameters) => CanonicalFormChoiceParameters::Typed { parameters, slot },
        None => CanonicalFormChoiceParameters::OpaqueSameProfile {
            raw: raw.to_owned(),
            slot,
        },
    }
}

/// Reads `<AvailableTypes>` out of `InputFieldSlot::AvailableTypes`.
///
/// The slot is an ordinary serialized type pattern, so it goes through the same
/// `parse_form_type_pattern` grammar as every other form type block. An empty
/// pattern is `Absent`, not an empty element: of the 49 951 native `InputField`
/// option tuples 49 937 hold the empty pattern and the platform writes no
/// `<AvailableTypes>` on any of their items, and it never writes the element
/// empty - all 14 blocks it does write carry at least one type.
pub(super) fn canonical_form_input_field_available_types(
    schema: FormFieldSchema,
    options: &[&str],
    type_index: &BTreeMap<String, String>,
) -> CanonicalFormChoiceParameterAvailableTypes {
    let slot = InputFieldSlot::AvailableTypes.index();
    let Some(raw) = schema.input_field_option(options, InputFieldSlot::AvailableTypes) else {
        return FormChoiceParameterAvailableTypes::Absent;
    };
    match parse_form_type_pattern(raw.trim(), type_index) {
        Some(value_types) if value_types.is_empty() => FormChoiceParameterAvailableTypes::Absent,
        Some(value_types) => FormChoiceParameterAvailableTypes::Typed(value_types),
        // Unobserved on the whole native tree: the slot parses on all 49 951
        // tuples. Kept as a typed refusal with a diagnostic rather than a silent
        // omission, so an unknown pattern is reported instead of dropped.
        None => FormChoiceParameterAvailableTypes::Opaque(OpaqueFormChoiceParameterClusterValue {
            raw: raw.to_owned(),
            slot,
        }),
    }
}

pub(super) fn parse_form_input_field_choice_parameters(
    field: &str,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<FormChoiceParameters> {
    let parameters = parse_form_choice_parameters(field, |type_id, value_id| {
        parse_form_enum_design_time_reference(
            type_id,
            value_id,
            type_index,
            type_index_collisions,
            object_refs,
        )
    })?;
    Some(parameters)
}

pub(super) fn parse_form_enum_design_time_reference(
    type_id: &str,
    value_id: &str,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let type_uuid = Uuid::parse_str(type_id.trim()).ok()?;
    let value_uuid = Uuid::parse_str(value_id.trim()).ok()?;
    if type_uuid.is_nil() {
        return None;
    }
    let type_reference =
        unique_metadata_type_reference(type_index, type_index_collisions, type_id.trim())?;
    let owner = parse_generated_metadata_reference_owner(type_reference)?;
    let owner_reference = owner.owner_reference();
    // A nil value id under a named reference type is not a missing id: it is
    // that type's empty reference, which needs no value index at all because
    // the whole name comes from the type. Evidence: UT 11.5.27.75, the 13
    // choice-parameter values the slot spells this way -- 8 under
    // `cfg:EnumRef.ВариантыРасчетаЦенНаборов` (4 scalar, 4 inside a fixed
    // array), 4 under `cfg:CatalogRef.СостоянияПроцессов` and 1 under
    // `cfg:CatalogRef.СегментыПартнеров`; the platform writes
    // `Enum.ВариантыРасчетаЦенНаборов.EmptyRef`,
    // `Catalog.СостоянияПроцессов.EmptyRef` and
    // `Catalog.СегментыПартнеров.EmptyRef` on every one, with no other
    // spelling and no counter-example.
    if value_uuid.is_nil() {
        return Some(format!("{owner_reference}.EmptyRef"));
    }
    if owner.kind() != GeneratedMetadataReferenceOwnerKind::Enum {
        // Outside an enumeration the value identifier names a *predefined
        // item* of the owner, which is not a metadata object and therefore has
        // no entry of its own in the reference index; the owner-qualified
        // predefined-item name is the only thing that can name it, and the
        // refusal here used to swallow every such reference -- and with it, in
        // a choice parameter, the whole `<ChoiceParameters>` block.
        //
        // Evidence: UT 11.5.27.75, equality of sets over every design-time
        // reference the form writer renders as a bare identifier pair. 61 such
        // pairs exist in the export; the 8 whose type identifier names a
        // configuration type *and* whose value identifier is a predefined item
        // of that type are exactly the 8 the platform spells out
        // (`Catalog.СтавкиНДС.БезНДС`,
        // `Catalog.КлассификаторНСИЗЕРНО.ТипХранения*` and five
        // `ChartOfCharacteristicTypes.СтатьиРасходов.*`), character for
        // character; the other 53 name a type the configuration no longer
        // carries, and the platform keeps the identifier pair on every one of
        // them, which is what returning `None` here still does.
        return form_predefined_item_reference(&owner_reference, &value_uuid, object_refs);
    }
    let value_ref = parse_design_time_reference(value_id.trim(), object_refs)?;
    let enum_value_prefix = format!("{owner_reference}.EnumValue.");
    value_ref
        .strip_prefix(&enum_value_prefix)
        .is_some_and(|name| !name.is_empty())
        .then_some(value_ref)
}

/// The name of the predefined item a design-time reference pair names, or
/// `None` when the pair names no object this configuration carries.
///
/// This is the fallback of the choice-list value reader, whose primary answer
/// is the plain value-identifier lookup: an enumeration value is a metadata
/// object in its own right and resolves there, a predefined item is not and
/// only resolves through its owner.
pub(super) fn form_predefined_item_design_time_reference(
    type_id: &str,
    value_id: &str,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let value_uuid = Uuid::parse_str(value_id.trim()).ok()?;
    if value_uuid.is_nil() {
        return None;
    }
    let type_reference =
        unique_metadata_type_reference(type_index, type_index_collisions, type_id.trim())?;
    let owner = parse_generated_metadata_reference_owner(type_reference)?;
    form_predefined_item_reference(&owner.owner_reference(), &value_uuid, object_refs)
}

/// The name of a predefined item of `owner_reference`, from the owner-qualified
/// entries the form reference index carries alongside the metadata objects.
pub(super) fn form_predefined_item_reference(
    owner_reference: &str,
    value_uuid: &Uuid,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    object_refs
        .get(&format!("owner-value:{owner_reference}:{value_uuid}"))
        .cloned()
}

#[allow(clippy::too_many_arguments)]
pub(super) fn parse_form_input_field_type_link(
    options: Option<&[&str]>,
    attribute_names_by_id: &BTreeMap<String, String>,
    data_path_by_table_column: &BTreeMap<(String, String), String>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> Option<FormTypeLink> {
    let options = options.filter(|options| {
        options.len() == 66 && options.first().map(|field| field.trim()) == Some("36")
    })?;
    let fields = options
        .get(InputFieldSlot::TypeLink.index())
        .and_then(|field| split_1c_braced_fields(field.trim(), 0))?;
    if fields.first().map(|field| field.trim()) != Some("3") {
        return None;
    }
    // The slot is a bound chain wearing a frame: `{3,<K>,<s1>,…,<sK>,<link>}`
    // holds the very same `{K,s1,…,sK}` every data-path slot holds, with the
    // link-item flag after it. So the chain is lifted out of the frame and
    // resolved exactly as a data path is resolved, instead of spelling out the
    // handful of chain shapes this route happened to learn first -- a
    // whitelist which refused four of the five terminal shapes the
    // configuration actually carries.
    //
    // Evidence: UT 11.5.27.75.
    // `Documents/СписаниеНДСНаРасходы/Forms/ФормаДокумента` InputField
    // `АналитикаРасходов` carries `{3,2,{1},{0,383b2b0a-…},0}`, whose chain
    // `{2,{1},{0,383b2b0a-…}}` is the `СтатьяРасходов` attribute of the
    // document reached from form attribute 1, written `Объект.СтатьяРасходов`;
    // the same item's `<ChoiceParameterLinks>` states that very path from the
    // very same two-member terminal.
    // `Catalogs/Новости/Forms/ФормаДокумента` InputField
    // `КатегорииПростыеЗначениеКатегорииНовостей` carries
    // `{3,2,{59,02023637-…},{0,80c61119-…},0}`, a metadata terminal under table
    // item 59, written
    // `Items.КатегорииПростые.CurrentData.КатегорияНовостей`.
    // `Documents/ВводОстатков/Forms/ФормаРасчетыМеждуОрганизациями` InputField
    // `РасчетыПоРеализацииРасчетныйДокумент` carries
    // `{3,2,{77,02023637-…},{1,5bdad865-…},0}`, an additional column of table
    // item 77, written `Items.РасчетыПоРеализации.CurrentData.ТипРасчетов`.
    // The one-member owner `{1}` and the two-member terminals are all readable;
    // only the arms that demanded a two-member owner and a one-member terminal
    // were not.
    let link_item = match fields.last()?.trim() {
        "0" => "0",
        "1" => "1",
        _ => return None,
    };
    if fields.len() < 3 {
        return None;
    }
    let chain = format!(
        "{{{}}}",
        fields[1..fields.len() - 1]
            .iter()
            .map(|field| field.trim())
            .collect::<Vec<_>>()
            .join(",")
    );
    let data_path = resolve_form_type_link_chain(
        &chain,
        attribute_names_by_id,
        data_path_by_table_column,
        table_name_by_id,
        table_column_names_by_id,
        owner_scoped_bindings,
        object_refs,
    )?;
    Some(FormTypeLink {
        data_path,
        link_item,
    })
}

/// Resolves the chain a type-link slot frames, through the same routes a data
/// path slot goes through.
#[allow(clippy::too_many_arguments)]
fn resolve_form_type_link_chain(
    chain: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    data_path_by_table_column: &BTreeMap<(String, String), String>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    resolve_form_item_scoped_current_data_path(
        chain,
        table_name_by_id,
        table_column_names_by_id,
        data_path_by_table_column,
        object_refs,
        owner_scoped_bindings,
    )
    .or_else(|| {
        resolve_form_item_rooted_chain_data_path(
            chain,
            table_name_by_id,
            owner_scoped_bindings,
            object_refs,
        )
    })
    .or_else(|| {
        resolve_form_bound_chain_member_path(
            chain,
            attribute_names_by_id,
            owner_scoped_bindings,
            object_refs,
            false,
        )
    })
}

