/// The optional-member bitmask a form font tuple carries in its third slot.
///
/// A form font tuple is `{7,<kind>,<mask>[,<style ref>],<present values...>,1,<scale>}`.
/// Every attribute the platform writes on a `<Font>`/`<TitleFont>` element
/// corresponds to one mask bit; an attribute whose bit is clear is simply
/// absent from both the tuple and the XML. The values themselves appear in
/// the tuple in `FORM_FONT_MASK_MEMBERS` order, which is *not* the attribute
/// order the platform writes -- `faceName` is stored last but written first.
///
/// Bit assignments and the value order are the ones that reproduce all 3 674
/// `<Font>`/`<TitleFont>` elements of the 5 201 native "1С:Управление
/// торговлей 11.5.27.75" form dumps with no misses and no false positives.
const FORM_FONT_MASK_MEMBERS: [(u32, FormFontMember); 6] = [
    (1, FormFontMember::Height),
    (2, FormFontMember::Bold),
    (3, FormFontMember::Italic),
    (4, FormFontMember::Underline),
    (5, FormFontMember::Strikeout),
    (0, FormFontMember::FaceName),
];

/// The bit that makes the platform write the trailing `scale` attribute even
/// when the tuple's scale value is the `100` default.
const FORM_FONT_MASK_SCALE_BIT: u32 = 9;

/// The attribute order the platform writes, independent of the tuple order.
const FORM_FONT_XML_ATTRIBUTE_ORDER: [FormFontMember; 6] = [
    FormFontMember::FaceName,
    FormFontMember::Height,
    FormFontMember::Bold,
    FormFontMember::Italic,
    FormFontMember::Underline,
    FormFontMember::Strikeout,
];

#[derive(Clone, Copy, PartialEq, Eq)]
enum FormFontMember {
    FaceName,
    Height,
    Bold,
    Italic,
    Underline,
    Strikeout,
}

impl FormFontMember {
    fn attribute(self) -> &'static str {
        match self {
            Self::FaceName => "faceName",
            Self::Height => "height",
            Self::Bold => "bold",
            Self::Italic => "italic",
            Self::Underline => "underline",
            Self::Strikeout => "strikeout",
        }
    }
}

/// The system-font identifier a `kind == "1"` form font tuple carries at its
/// own slot 3, wrapped in a single-element tuple (`{0}`, `{2}`, ...).
///
/// Evidence: three independent already-proven fixtures for the structurally
/// identical `{7,1,<mask>,{0},...}` tuple this same project decodes
/// elsewhere (a DCS font `Value`, an MXL cell font, and a style's own font)
/// all carry `{0}` and all three write `sys:DefaultGUIFont`, matching every
/// one of 227 native `<Font ref="sys:DefaultGUIFont".../>` elements this
/// crate's own output already reproduces correctly. SSL demo 3.1.12.297 adds
/// the corpus's only other code:
/// `DataProcessors/КонсольЗапросов`'s `ПланВыполненияЗапроса` form carries
/// two `TextDocumentField`s whose tuple reads `{2}` there and whose native
/// `<Font>` is `ref="sys:ANSIFixedFont"`, on both, byte for byte. No other
/// code occurs in either corpus, so an unrecognized one is a refusal rather
/// than a guessed name.
fn parse_form_font_system_name_ref(field: &str) -> Option<&'static str> {
    let wrapped = split_1c_braced_fields(field, 0)?;
    if wrapped.len() != 1 {
        return None;
    }
    match wrapped.first()?.trim() {
        "0" => Some("sys:DefaultGUIFont"),
        "2" => Some("sys:ANSIFixedFont"),
        _ => None,
    }
}

/// Decodes a form font tuple into the element the platform writes for it.
///
/// `None` means the platform writes no element at all: an `AutoFont` tuple
/// with an empty mask (the ubiquitous `{7,3,0,1,100}` default), a slot that
/// does not hold a font tuple at all, a member count that disagrees with the
/// mask, a `WindowsFont` kind whose system-font code is not recognized, or a
/// `StyleItem` kind whose style reference cannot be resolved -- every native
/// `WindowsFont`/`StyleItem` font carries a `ref`, so an unresolved one is a
/// refusal rather than a `ref`-less guess.
fn parse_form_font_mask_tuple_xml(
    field: &str,
    object_refs: &BTreeMap<String, String>,
    tag_name: &str,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first()?.trim() != "7" {
        return None;
    }
    let kind = fields.get(1)?.trim();
    let mask = fields.get(2)?.trim().parse::<u32>().ok()?;
    let mut attributes = Vec::<(&str, String)>::new();
    let (kind_xml, value_start) = match kind {
        "0" => {
            // The absolute kind spells every member out in a fixed 19-slot
            // layout instead of packing the present ones behind the mask.
            if fields.len() != 19 {
                return None;
            }
            attributes.push((
                "faceName",
                parse_1c_quoted_string(fields.get(16)?.trim()).unwrap_or_default(),
            ));
            attributes.push(("height", form_font_mask_height(fields.get(3)?.trim())?));
            attributes.push(("bold", form_font_mask_bold(fields.get(7)?.trim())?));
            for (slot, member) in [
                (8, FormFontMember::Italic),
                (9, FormFontMember::Underline),
                (10, FormFontMember::Strikeout),
            ] {
                attributes.push((
                    member.attribute(),
                    form_font_mask_flag(fields.get(slot)?.trim())?,
                ));
            }
            attributes.push(("kind", "Absolute".to_string()));
            if (mask >> FORM_FONT_MASK_SCALE_BIT) & 1 == 1 {
                attributes.push(("scale", fields.get(18)?.trim().to_string()));
            }
            let rendered = attributes
                .iter()
                .map(|(name, value)| format!(" {name}=\"{}\"", escape_xml_text(value)))
                .collect::<String>();
            return Some(format!("<{tag_name}{rendered}/>"));
        }
        "1" => {
            let name = parse_form_font_system_name_ref(fields.get(3)?.trim())?;
            attributes.push(("ref", name.to_string()));
            ("WindowsFont", 4)
        }
        "2" => {
            attributes.push(("ref", parse_form_font_style_ref(&fields, object_refs)?));
            ("StyleItem", 4)
        }
        "3" => ("AutoFont", 3),
        _ => return None,
    };
    let values = fields.get(value_start..fields.len().checked_sub(2)?)?;
    let present = FORM_FONT_MASK_MEMBERS
        .iter()
        .filter(|(bit, _)| (mask >> bit) & 1 == 1)
        .map(|(_, member)| *member)
        .collect::<Vec<_>>();
    if present.len() != values.len() {
        return None;
    }
    let scale = (mask >> FORM_FONT_MASK_SCALE_BIT) & 1 == 1;
    if present.is_empty() && !scale && kind_xml == "AutoFont" {
        return None;
    }
    for member in FORM_FONT_XML_ATTRIBUTE_ORDER {
        let Some(index) = present.iter().position(|candidate| *candidate == member) else {
            continue;
        };
        let raw = values.get(index)?.trim();
        let value = match member {
            FormFontMember::FaceName => parse_1c_quoted_string(raw)?,
            FormFontMember::Height => form_font_mask_height(raw)?,
            FormFontMember::Bold => form_font_mask_bold(raw)?,
            _ => form_font_mask_flag(raw)?,
        };
        attributes.push((member.attribute(), value));
    }
    attributes.push(("kind", kind_xml.to_string()));
    if scale {
        attributes.push(("scale", fields.last()?.trim().to_string()));
    }
    let rendered = attributes
        .iter()
        .map(|(name, value)| format!(" {name}=\"{}\"", escape_xml_text(value)))
        .collect::<String>();
    Some(format!("<{tag_name}{rendered}/>"))
}

/// Font heights are stored in tenths of a point and written whole, including
/// the `height="0"` the platform writes for a zero-tenths height.
fn form_font_mask_height(raw: &str) -> Option<String> {
    Some((raw.parse::<i32>().ok()? / 10).to_string())
}

fn form_font_mask_bold(raw: &str) -> Option<String> {
    Some(xml_bool(raw.parse::<i32>().ok()? >= 700).to_string())
}

fn form_font_mask_flag(raw: &str) -> Option<String> {
    match raw {
        "0" => Some("false".to_string()),
        "1" => Some("true".to_string()),
        _ => None,
    }
}

fn parse_form_button_font_tuple_xml(
    field: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    parse_form_font_mask_tuple_xml(field, object_refs, "Font")
}

pub(super) fn parse_form_font_style_ref(
    fields: &[&str],
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    if fields.get(1).map(|value| value.trim()) != Some("2") {
        return None;
    }
    let style_slot = split_1c_braced_fields(fields.get(3)?.trim(), 0)?;
    if style_slot.len() == 1 {
        let code = style_slot.first()?.trim().parse::<i32>().ok()?;
        return standard_style_item_for_code(code).map(|(_, name)| format!("style:{name}"));
    }
    if style_slot.first().map(|value| value.trim()) != Some("0") {
        return None;
    }
    let uuid = parse_uuid_field(style_slot.get(1)?.trim())?;
    moxel_style_ref_for_uuid(&uuid, object_refs)
}

pub(super) fn parse_form_input_field_skip_on_input(field: &str) -> Option<bool> {
    match field.trim() {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

/// A `MinValue`/`MaxValue` bound: the platform spells the element's `xsi:type`
/// from the kind marker of the stored value, so the two travel together.
#[derive(Debug, Clone, Eq, PartialEq)]
pub(super) struct FormInputBoundValue {
    pub(super) xsi_type: &'static str,
    pub(super) text: String,
}

/// `MinValue`/`MaxValue` of an `InputField`, with the type the platform writes.
///
/// UT 11.5.27.75, all `InputField` option tuples: slot 16 holds the undefined
/// marker on 34 752 items that carry no `<MinValue>`, an `{"N", n}` number on
/// 151 that carry `xsi:type="xs:decimal"` with exactly that number, and an
/// `{"S", s}` string on 4 that carry `xsi:type="xs:string"` with exactly that
/// string.  Slot 17 posts the same three shapes and the same score for
/// `<MaxValue>` (34 826 / 80 / 1).  No other kind marker occurs in either slot,
/// so the string form was not an unreadable value but an unread one.
fn parse_form_input_field_decimal_option(
    schema: FormFieldSchema,
    options: &[&str],
    slot: InputFieldSlot,
) -> Option<FormInputBoundValue> {
    let raw = schema.input_field_option(options, slot)?.trim();
    if scan_1c_braced_value(raw, 0) != Some(raw.len()) {
        return None;
    }
    let value = split_1c_braced_fields(raw, 0)?;
    match value.as_slice() {
        [kind, decimal]
            if kind.trim() == r#""N""# && information_register_decimal_is_valid(decimal.trim()) =>
        {
            Some(FormInputBoundValue {
                xsi_type: "xs:decimal",
                text: decimal.trim().to_string(),
            })
        }
        [kind, text] if kind.trim() == r#""S""# => {
            parse_exact_1c_quoted_string(text.trim()).map(|text| FormInputBoundValue {
                xsi_type: "xs:string",
                text,
            })
        }
        [kind] if kind.trim() == r#""U""# => None,
        _ => None,
    }
}

