pub(super) fn parse_form_child_item_data_path(
    tag: &str,
    fields: &[&str],
    name: &str,
    id: &str,
    main_data_path: Option<&str>,
    parent_data_path: Option<&str>,
    strict_field_data_path: bool,
    owner_scoped_data_path: bool,
    button_data_path_slot: Option<usize>,
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    data_path_by_binding_key: &BTreeMap<String, String>,
    bound_table_path_by_binding_key: &BTreeMap<String, String>,
    table_column_names_by_binding_key: &BTreeMap<String, BTreeMap<String, String>>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> FormChildItemDataPaths {
    let owner_scoped_metadata = !matches!(tag, "ProgressBarField" | "TrackBarField" | "ChartField");
    // An item that sits inside the table it addresses reads the row's own
    // column; one that sits outside reads the column total. Nothing in the slot
    // tells the two apart.
    let aggregate_member = parent_data_path.is_none();
    let parse_bound_slot = |field: &str, aggregate: bool| {
        let chain = FormOwnerScopedDataPath::from_option(
            resolve_form_settings_composer_chain_data_path(
                field,
                attribute_metadata_owners_by_id,
                object_refs,
                &owner_scoped_bindings.metadata_field_types,
            )
            .or_else(|| {
                resolve_form_standard_period_column_data_path(
                    field,
                    attribute_metadata_owners_by_id,
                )
            })
            .or_else(|| {
                resolve_form_bound_chain_member_path(
                    field,
                    attribute_names_by_id,
                    owner_scoped_bindings,
                    object_refs,
                    aggregate,
                )
            })
            // A dynamic list's own negative member is named by the source,
            // so it is read before the routes that spell a name the source
            // never states. The table-path index reached `{2,{2},{-2}}` on
            // `DataProcessors/СервисSellmonitor/Forms/ПодборКарточекТоваров`
            // and answered it with the bound item's own name,
            // `СписокМаркетплейсOzon.СписокМаркетплейсOzonОтбор`, where the
            // platform writes `СписокМаркетплейсOzon.Filter`.
            .or_else(|| {
                resolve_form_dynamic_list_member_data_path(field, attribute_metadata_owners_by_id)
            }),
        );
        if !matches!(chain, FormOwnerScopedDataPath::Unknown) {
            return chain;
        }
        let scoped = if strict_field_data_path {
            FormOwnerScopedDataPath::from_option(resolve_form_strict_field_model_data_path(
                field,
                attribute_metadata_owners_by_id,
                object_refs,
            ))
        } else {
            FormOwnerScopedDataPath::Unknown
        }
        .or_else(|| {
            if owner_scoped_data_path {
                resolve_form_owner_scoped_bound_data_path(
                    field,
                    attribute_metadata_owners_by_id,
                    owner_scoped_bindings,
                    object_refs,
                )
            } else {
                FormOwnerScopedDataPath::Unknown
            }
        });
        scoped
            .or_else(|| {
                FormOwnerScopedDataPath::from_option(resolve_form_item_scoped_current_data_path(
                    field,
                    table_name_by_id,
                    table_column_names_by_id,
                    type_link_data_path_by_table_column,
                    object_refs,
                    owner_scoped_bindings,
                ))
            })
            // A slot whose owner is a form item is a chain like any other; the
            // two-segment route above answers the shapes it knows, and the
            // chain walker answers the rest against the namespace the table
            // stands in.
            .or_else(|| {
                FormOwnerScopedDataPath::from_option(
                    resolve_form_item_rooted_settings_composer_path(
                        field,
                        table_name_by_id,
                        owner_scoped_bindings,
                    )
                    .or_else(|| {
                        resolve_form_item_rooted_chain_data_path(
                            field,
                            table_name_by_id,
                            owner_scoped_bindings,
                            object_refs,
                        )
                    })
                    .or_else(|| {
                        resolve_form_dynamic_list_member_data_path(
                            field,
                            attribute_metadata_owners_by_id,
                        )
                    }),
                )
            })
            .or_else(|| {
                let data_path = if owner_scoped_metadata {
                    parse_form_bound_data_path_with_metadata_owner(
                        field,
                        name,
                        attribute_names_by_id,
                        attribute_metadata_owners_by_id,
                        table_name_by_id,
                        table_column_names_by_id,
                        bound_table_path_by_binding_key,
                        table_column_names_by_binding_key,
                        object_refs,
                    )
                } else {
                    parse_form_bound_data_path(
                        field,
                        name,
                        attribute_names_by_id,
                        table_name_by_id,
                        table_column_names_by_id,
                        bound_table_path_by_binding_key,
                        table_column_names_by_binding_key,
                    )
                };
                FormOwnerScopedDataPath::from_option(data_path)
            })
    };
    let parse_direct_slot = |field: &str, aggregate: bool| {
        parse_bound_slot(field, aggregate).or_else(|| {
            // A chain whose leaf names a metadata attribute is the same
            // binding one segment shorter plus that attribute's name.
            let Some((prefix, suffix)) = split_form_metadata_attribute_tail(field, object_refs)
            else {
                return FormOwnerScopedDataPath::Unknown;
            };
            match parse_bound_slot(&prefix, aggregate) {
                FormOwnerScopedDataPath::Resolved(prefix_path) => {
                    FormOwnerScopedDataPath::Resolved(format!("{prefix_path}.{suffix}"))
                }
                unresolved => unresolved,
            }
        })
    };
    let parse_direct_bound = |field: &&str| {
        parse_direct_slot(field, aggregate_member)
            .with_provenance(FormChildItemDataPathProvenance::DirectRawSlot)
    };
    let parse_bound = |field: &&str| {
        parse_direct_bound(field).or_else(|| {
            let data_path = parse_form_bound_data_binding_key(field)
                .and_then(|binding_key| data_path_by_binding_key.get(&binding_key).cloned());
            FormChildItemDataPathResolution::from_option(
                data_path,
                FormChildItemDataPathProvenance::InferredFallback,
            )
        })
    };
    let resolve_slots =
        |slots: &[usize], resolver: &dyn Fn(&&str) -> FormChildItemDataPathResolution| {
            for slot in slots {
                if let Some(field) = fields.get(*slot) {
                    match resolver(field) {
                        FormChildItemDataPathResolution::Unknown => {}
                        resolved => return resolved,
                    }
                }
            }
            FormChildItemDataPathResolution::Unknown
        };
    let field_layout_tag = matches!(
        tag,
        "InputField"
            | "LabelField"
            | "CheckBoxField"
            | "PictureField"
            | "RadioButtonField"
            | "TextDocumentField"
            | "FormattedDocumentField"
            | "CalendarField"
            | "GraphicalSchemaField"
            | "SpreadSheetDocumentField"
            | "HTMLDocumentField"
            | "ProgressBarField"
            | "TrackBarField"
            | "ChartField"
    );
    let input_field_offset = field_layout_tag
        .then(|| {
            form_input_field_layout_is_extended(fields)
                .then(|| form_input_field_top_level_offset(fields))
        })
        .flatten()
        .unwrap_or(0);
    let input_slots = [11 + input_field_offset, 12 + input_field_offset];
    // Both bound slots spelling the empty binding `{0}` is the platform's own
    // statement that the item shows no data, and it then writes no `DataPath`
    // at all -- 280 such items across UT 11.5.27.75, every one of them without
    // the element. Naming the parent path plus the item's own name instead is a
    // guess, and it is wrong for all 77 of those the guess reached.
    let unbound_slots = button_data_path_slot.is_none()
        && fields.get(input_slots[0]).map(|field| field.trim()) == Some("{0}")
        && matches!(
            fields.get(input_slots[1]).map(|field| field.trim()),
            None | Some("{0}")
        );
    if unbound_slots {
        return FormChildItemDataPaths::default();
    }
    // The second bound slot is the column footer's own binding, written in the
    // same chain grammar as the first. Over all 59 149 field items UT
    // 11.5.27.75 spells out, the slot holds the empty binding `{0}` on exactly
    // the 58 936 that carry no `<FooterDataPath>` and a chain on exactly the
    // 213 that do, with no counter-example either way. The aggregate marker is
    // read as the aggregate it names here: a footer states the column total
    // even when the item sits inside the table it addresses, which is the one
    // place the primary slot's placement rule does not reach.
    let footer_data_path = field_layout_tag
        .then(|| fields.get(input_slots[1]))
        .flatten()
        .filter(|field| field.trim() != "{0}")
        .and_then(|field| match parse_direct_slot(field, true) {
            FormOwnerScopedDataPath::Resolved(data_path) => Some(data_path),
            FormOwnerScopedDataPath::Unknown | FormOwnerScopedDataPath::Ambiguous => None,
        });
    // The multiple-value editor keeps its own two bound slots in a twenty-member
    // bag the extended option bag carries at slot 62. Across all 34 838
    // `InputField` items UT 11.5.27.75 spells out, only 6 carry that bag at all
    // and only 3 have its first binding set -- exactly the 3 the platform writes
    // `<MultipleValueDataPath>` and `<MultipleValuePresentDataPath>` for. Member
    // 9 is the value path and member 15 the presentation path: the item over
    // `ТипСуммы` declares `Наименование` before `Код` yet still spells `Код` at
    // member 9, so the two are told apart by position and not by the order the
    // attribute declares its columns. Member 12 is bound on none of the 34 838.
    let multiple_value_paths = (tag == "InputField")
        .then(|| form_input_field_extended_options(fields))
        .flatten()
        .and_then(|options| {
            let members = split_1c_braced_fields(options.get(62)?.trim(), 0)?;
            if members.len() != 20 {
                return None;
            }
            let attribute_id =
                parse_form_single_segment_chain_id(fields.get(input_slots[0])?.trim())?;
            let resolve = |member: usize| {
                resolve_form_attribute_declared_column_path(
                    members.get(member)?.trim(),
                    &attribute_id,
                    attribute_names_by_id,
                    owner_scoped_bindings,
                )
            };
            Some((resolve(9), resolve(15)))
        })
        .unwrap_or((None, None));
    let data_path = match tag {
        // The empty binding `{0}` is the platform's own statement that the
        // table shows no data, exactly as it is on a field, and the platform
        // then writes no `<DataPath>` at all. Falling back to the form's main
        // attribute puts a path on a table the platform leaves bare.
        "Table" if fields.get(11).map(|field| field.trim()) == Some("{0}") => {
            FormChildItemDataPathResolution::Unknown
        }
        "Table" => fields
            .get(11)
            .map(parse_bound)
            .unwrap_or(FormChildItemDataPathResolution::Unknown)
            .or_else(|| {
                FormChildItemDataPathResolution::from_option(
                    main_data_path.map(ToOwned::to_owned),
                    FormChildItemDataPathProvenance::InferredFallback,
                )
            }),
        "InputField"
        | "CheckBoxField"
        | "PictureField"
        | "RadioButtonField"
        | "FormattedDocumentField"
        | "ProgressBarField"
        | "TrackBarField"
        | "ChartField" => resolve_slots(&input_slots, &parse_bound).or_else(|| {
            FormChildItemDataPathResolution::from_option(
                parent_data_path.map(|parent| {
                    let name = normalize_form_data_path_child_name(parent, name);
                    format!("{parent}.{name}")
                }),
                FormChildItemDataPathProvenance::InferredFallback,
            )
        }),
        "CalendarField"
        | "GraphicalSchemaField"
        | "SpreadSheetDocumentField"
        | "HTMLDocumentField"
        // The PDF viewer field spells its binding in the same slot 11 the
        // other document fields do: all five items of UT 11.5.27.75 hold a
        // one-segment chain there naming the form attribute the platform
        // writes in `<DataPath>`, and none of them falls back to a parent path.
        | "PDFDocumentField" => resolve_slots(&input_slots, &parse_bound),
        "LabelField" => resolve_slots(&input_slots, &parse_direct_bound),
        "TextDocumentField" => resolve_slots(&input_slots, &parse_bound),
        "Button" => button_data_path_slot
            .and_then(|slot| fields.get(slot))
            .map(|field| {
                resolve_form_owner_scoped_button_data_path(
                    field,
                    attribute_names_by_id,
                    attribute_metadata_owners_by_id,
                    table_name_by_id,
                    table_column_names_by_id,
                    type_link_data_path_by_table_column,
                    owner_scoped_bindings,
                    object_refs,
                )
                .with_provenance(FormChildItemDataPathProvenance::DirectRawSlot)
            })
            .unwrap_or(FormChildItemDataPathResolution::Unknown),
        _ => FormChildItemDataPathResolution::from_option(
            table_name_by_id.get(id).cloned(),
            FormChildItemDataPathProvenance::InferredFallback,
        ),
    };
    let paths = FormChildItemDataPaths {
        primary: data_path.into_option(),
        footer: footer_data_path,
        multiple_value: multiple_value_paths.0,
        multiple_value_present: multiple_value_paths.1,
    };
    paths
}

/// The id a one-segment bound chain `{1,{<id>}}` names, and nothing else.
fn parse_form_single_segment_chain_id(field: &str) -> Option<String> {
    let segments = parse_form_bound_chain_segments(field)?;
    let [only] = segments.as_slice() else {
        return None;
    };
    let [id] = only.as_slice() else {
        return None;
    };
    Some(parse_form_chain_numeric_id(id)?.to_string())
}

/// Spells out a bound slot that names one column an attribute declares, given
/// the attribute from elsewhere.
///
/// This is the `{c}` segment of the chain grammar standing on its own: the slot
/// carries the column id with no attribute ahead of it, because the attribute is
/// the one the item is already bound to. The column name comes from the same
/// declared-column index the chain walker reads.
fn resolve_form_attribute_declared_column_path(
    field: &str,
    attribute_id: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
) -> Option<String> {
    let column_id = parse_form_single_segment_chain_id(field)?;
    let key = FormAttributeColumnKey {
        attribute_id: attribute_id.to_string(),
        column_id,
    };
    let column = owner_scoped_bindings.declared_columns.get(&key)?.as_ref()?;
    let attribute = attribute_names_by_id.get(attribute_id)?;
    Some(format!("{attribute}.{column}"))
}

/// The two bound data paths a field item spells out: the one it edits and the
/// one its column footer shows.
#[derive(Default)]
pub(super) struct FormChildItemDataPaths {
    pub(super) primary: Option<ResolvedFormChildItemDataPath>,
    pub(super) footer: Option<String>,
    pub(super) multiple_value: Option<String>,
    pub(super) multiple_value_present: Option<String>,
}

pub(super) struct ResolvedFormChildItemDataPath {
    data_path: String,
    provenance: FormChildItemDataPathProvenance,
}

enum FormChildItemDataPathResolution {
    Unknown,
    Ambiguous,
    Resolved(ResolvedFormChildItemDataPath),
}

impl FormChildItemDataPathResolution {
    fn from_option(data_path: Option<String>, provenance: FormChildItemDataPathProvenance) -> Self {
        data_path
            .map(|data_path| {
                Self::Resolved(ResolvedFormChildItemDataPath {
                    data_path,
                    provenance,
                })
            })
            .unwrap_or(Self::Unknown)
    }

    fn or_else(self, fallback: impl FnOnce() -> Self) -> Self {
        match self {
            Self::Unknown => fallback(),
            resolved => resolved,
        }
    }

    fn into_option(self) -> Option<ResolvedFormChildItemDataPath> {
        match self {
            Self::Resolved(resolved) => Some(resolved),
            Self::Unknown | Self::Ambiguous => None,
        }
    }
}

enum FormOwnerScopedDataPath {
    Unknown,
    Ambiguous,
    Resolved(String),
}

impl FormOwnerScopedDataPath {
    fn from_option(data_path: Option<String>) -> Self {
        data_path.map(Self::Resolved).unwrap_or(Self::Unknown)
    }

    fn or_else(self, fallback: impl FnOnce() -> Self) -> Self {
        match self {
            Self::Unknown => fallback(),
            resolved => resolved,
        }
    }

    fn with_provenance(
        self,
        provenance: FormChildItemDataPathProvenance,
    ) -> FormChildItemDataPathResolution {
        match self {
            Self::Unknown => FormChildItemDataPathResolution::Unknown,
            Self::Ambiguous => FormChildItemDataPathResolution::Ambiguous,
            Self::Resolved(data_path) => {
                FormChildItemDataPathResolution::Resolved(ResolvedFormChildItemDataPath {
                    data_path,
                    provenance,
                })
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn resolve_form_owner_scoped_button_data_path(
    field: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> FormOwnerScopedDataPath {
    let no_global_binding_paths = BTreeMap::new();
    FormOwnerScopedDataPath::from_option(
        parse_form_button_data_path(
            field,
            attribute_names_by_id,
            table_name_by_id,
            table_column_names_by_id,
            type_link_data_path_by_table_column,
            &no_global_binding_paths,
        )
        // A button addresses its data in the same chain grammar every other
        // item uses, so a slot the button-only route cannot spell is read as
        // the chain it is rather than dropped. Evidence: UT 11.5.27.75
        // `Catalogs/СделкиСКлиентами/Forms/ФормаЭлемента`, Button `Кнопка`
        // carries `{2,{1},{0,2a0c92dc-…}}` against the `Объект` attribute and
        // the platform writes `<DataPath>Объект.ВидСделки</DataPath>`.
        .or_else(|| {
            resolve_form_bound_chain_member_path(
                field,
                attribute_names_by_id,
                owner_scoped_bindings,
                object_refs,
                false,
            )
        })
        // A negative marker on the root attribute names one of the standard
        // attributes that attribute's own type declares, read from the same
        // per-owner tables the field routes use. Evidence: UT 11.5.27.75
        // `ExchangePlans/ОбменССайтом/Forms/ФормаУзла`, Button
        // `ФормаПланОбменаОбменССайтомВыполнитьОбменДанными` carries
        // `{2,{1},{-6}}` against the `Объект` attribute of type
        // `cfg:ExchangePlanObject.ОбменССайтом`, and the platform writes
        // `<DataPath>Объект.Ref</DataPath>`.
        .or_else(|| {
            resolve_form_root_attribute_standard_attribute_path(
                field,
                attribute_metadata_owners_by_id,
            )
        }),
    )
}

/// `{2,{<attribute>},{<marker>}}` where the marker is a standard attribute of
/// the attribute's own exact type.
fn resolve_form_root_attribute_standard_attribute_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let [kind, owner, terminal] = fields.as_slice() else {
        return None;
    };
    if kind.trim() != "2" {
        return None;
    }
    let owner = split_1c_braced_fields(owner.trim(), 0)?;
    let terminal = split_1c_braced_fields(terminal.trim(), 0)?;
    let ([attribute_id], [marker]) = (owner.as_slice(), terminal.as_slice()) else {
        return None;
    };
    let marker = marker.trim();
    if !marker.starts_with('-') {
        return None;
    }
    let attribute = attribute_metadata_owners_by_id.get(attribute_id.trim())?;
    let reference = attribute.exact_single_type_reference.as_deref()?;
    let name = form_standard_attribute_name_for_type_reference(reference, marker)?;
    Some(format!("{}.{name}", attribute.name))
}

/// Resolves a multi-segment binding against a dynamic-list attribute.
///
/// A bound slot is a chain `{K,s1,…,sK}` of `K` segments. When the owner is a
/// dynamic list, every following segment is a numeric field-map id and the
/// field-map entry of the *leaf* id already spells out the whole relative path,
/// dots included — so the answer is the attribute name joined with that one
/// entry, never a join of the per-segment names.
///
/// Evidence: UT 11.5.27.75
/// `AccumulationRegisters/ОтклоненияВСтоимостиТоваров/Forms/ФормаСписка`,
/// InputField `АналитикаУчетаПоПартнерамПартнер` carries `{3,{1},{582},{2009}}`
/// against the `Список` dynamic list, whose field map holds `582` ->
/// `АналитикаУчетаПоПартнерам` and `2009` -> `АналитикаУчетаПоПартнерам.Партнер`;
/// the platform writes `<DataPath>Список.АналитикаУчетаПоПартнерам.Партнер</DataPath>`.
///
/// The leaf entry must carry exactly `K-1` dot-separated components, which is
/// what makes the chain and the field map corroborate each other; a leaf whose
/// shape disagrees with the chain length stays unresolved rather than guessed.
fn resolve_form_dynamic_list_chain_data_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
) -> FormOwnerScopedDataPath {
    let Some(segments) = parse_form_bound_chain_segments(field) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    if segments.len() < 3 {
        return FormOwnerScopedDataPath::Unknown;
    }
    let mut numeric = Vec::with_capacity(segments.len());
    for segment in &segments {
        let [id] = segment.as_slice() else {
            return FormOwnerScopedDataPath::Unknown;
        };
        let id = id.trim();
        if id.parse::<u64>().map(|value| value.to_string()) != Ok(id.to_string()) {
            return FormOwnerScopedDataPath::Unknown;
        }
        numeric.push(id);
    }
    let attribute_id = numeric[0];
    if !owner_scoped_bindings
        .dynamic_list_attribute_ids
        .contains(attribute_id)
    {
        return FormOwnerScopedDataPath::Unknown;
    }
    let key = FormAttributeColumnKey {
        attribute_id: attribute_id.to_string(),
        column_id: numeric[numeric.len() - 1].to_string(),
    };
    let Some(field_name) = owner_scoped_bindings.attribute_columns.get(&key) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    let Some(field_name) = field_name else {
        return FormOwnerScopedDataPath::Ambiguous;
    };
    if field_name.split('.').count() != numeric.len() - 1 {
        return FormOwnerScopedDataPath::Unknown;
    }
    let Some(attribute) = attribute_metadata_owners_by_id.get(attribute_id) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    FormOwnerScopedDataPath::Resolved(format!("{}.{}", attribute.name, field_name))
}

/// Splits a bound slot `{K,s1,…,sK}` into its `K` segments, each already split
/// into its own fields. The leading count must agree with the number of
/// segments actually present; a slot that disagrees is not a chain.
fn parse_form_bound_chain_segments(field: &str) -> Option<Vec<Vec<&str>>> {
    form_bound_chain_segment_fields(field)?
        .iter()
        .map(|segment| split_1c_braced_fields(segment.trim(), 0))
        .collect()
}

fn form_bound_chain_segment_fields(field: &str) -> Option<Vec<&str>> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let (count, segments) = fields.split_first()?;
    (count.trim().parse::<usize>().ok()? == segments.len()).then(|| segments.to_vec())
}

/// Peels a metadata-attribute leaf off a bound slot, returning the slot one
/// segment shorter plus the attribute name that leaf contributes.
///
/// A chain `{K,s1,…,sK}` whose last segment is `{0,<uuid>}` pointing at an
/// `…​.Attribute.<name>` reference addresses `<name>` on whatever the first
/// `K-1` segments address, so the whole path is the shorter binding's path with
/// `<name>` appended. Resolving the shorter binding through the ordinary
/// resolvers keeps every owner rule that applies to it in force, instead of
/// re-deriving the prefix from the item name.
///
/// Evidence: UT 11.5.27.75 `Documents/ВводОстатков/Forms/ФормаОптовыеПродажи`,
/// LabelField `ОптовыеПродажиНоменклатураЕдиницаИзмерения` carries
/// `{4,{1},{0,300cfbc7-…},{0,fb0ae716-…},{0,3d295926-…}}`, whose leaf uuid is
/// `Catalog.Номенклатура.Attribute.ЕдиницаИзмерения` and whose three-segment
/// prefix already exports as `Объект.ОптовыеПродажи.Номенклатура`; the platform
/// writes `<DataPath>Объект.ОптовыеПродажи.Номенклатура.ЕдиницаИзмерения</DataPath>`.
fn split_form_metadata_attribute_tail(
    field: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<(String, String)> {
    let segments = form_bound_chain_segment_fields(field)?;
    if segments.len() < 3 {
        return None;
    }
    let (leaf, prefix) = segments.split_last()?;
    let leaf = split_1c_braced_fields(leaf.trim(), 0)?;
    let [kind, uuid] = leaf.as_slice() else {
        return None;
    };
    if kind.trim() != "0" {
        return None;
    }
    let uuid = parse_non_zero_uuid(uuid.trim())?;
    let suffix = form_metadata_attribute_suffix(object_refs.get(&uuid)?)?;
    let prefix_field = format!(
        "{{{},{}}}",
        prefix.len(),
        prefix
            .iter()
            .map(|segment| segment.trim())
            .collect::<Vec<_>>()
            .join(",")
    );
    Some((prefix_field, suffix.to_string()))
}

fn resolve_form_owner_scoped_bound_data_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> FormOwnerScopedDataPath {
    let attribute_column = resolve_form_attribute_column_data_path(
        field,
        attribute_metadata_owners_by_id,
        owner_scoped_bindings,
    );
    if !matches!(attribute_column, FormOwnerScopedDataPath::Unknown) {
        return attribute_column;
    }
    let dynamic_list_field = resolve_form_dynamic_list_chain_data_path(
        field,
        attribute_metadata_owners_by_id,
        owner_scoped_bindings,
    );
    if !matches!(dynamic_list_field, FormOwnerScopedDataPath::Unknown) {
        return dynamic_list_field;
    }
    match resolve_form_owner_scoped_metadata_data_path_status(
        field,
        attribute_metadata_owners_by_id,
        object_refs,
    ) {
        FormMetadataDataPathResolution::Resolved(data_path) => {
            return FormOwnerScopedDataPath::Resolved(data_path);
        }
        FormMetadataDataPathResolution::Invalid => {
            return FormOwnerScopedDataPath::Ambiguous;
        }
        FormMetadataDataPathResolution::ForeignOwner => {
            // Only a two-segment binding pins the terminal on the owner
            // attribute itself; a longer chain routes through an intermediate
            // segment, so a foreign owner leaves the slot open for the
            // chain-aware resolvers rather than condemning it.
            if !form_bound_chain_segment_fields(field).is_some_and(|segments| segments.len() > 2) {
                return FormOwnerScopedDataPath::Ambiguous;
            }
        }
        FormMetadataDataPathResolution::NotMetadata
        | FormMetadataDataPathResolution::ReferenceAbsent => {}
    }
    let Some(fields) = split_1c_braced_fields(field.trim(), 0) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    let Some(owner) = fields
        .get(1)
        .and_then(|field| split_1c_braced_fields(field.trim(), 0))
    else {
        return FormOwnerScopedDataPath::Unknown;
    };
    if owner.len() != 1 {
        return FormOwnerScopedDataPath::Unknown;
    }
    let attribute_id = owner[0].trim().to_string();
    let Some(table_key) = fields
        .get(2)
        .and_then(|field| parse_form_binding_key(field.trim()))
    else {
        return FormOwnerScopedDataPath::Unknown;
    };
    let table_lookup = FormBoundTableKey {
        attribute_id: attribute_id.clone(),
        table_key: table_key.clone(),
    };
    let Some(table_path) = owner_scoped_bindings.table_paths.get(&table_lookup) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    let Some(table_path) = table_path.as_ref() else {
        return FormOwnerScopedDataPath::Ambiguous;
    };
    if fields.first().map(|field| field.trim()) == Some("2") {
        return FormOwnerScopedDataPath::Resolved(table_path.clone());
    }
    if fields.first().map(|field| field.trim()) != Some("3") {
        return FormOwnerScopedDataPath::Unknown;
    }
    let Some(column_key) = fields
        .get(3)
        .and_then(|field| parse_form_binding_key(field.trim()))
    else {
        return FormOwnerScopedDataPath::Unknown;
    };
    let column_lookup = FormBoundColumnKey {
        attribute_id,
        table_key,
        column_key,
    };
    match owner_scoped_bindings.column_names.get(&column_lookup) {
        Some(Some(column_name)) => {
            let column_name = normalize_form_table_column_name(table_path, column_name);
            FormOwnerScopedDataPath::Resolved(format!("{table_path}.{column_name}"))
        }
        Some(None) => FormOwnerScopedDataPath::Ambiguous,
        None => FormOwnerScopedDataPath::Unknown,
    }
}

/// The row-index segment of a bound chain: `{i,e67e2953-…}` addresses element
/// `i` of the collection the chain has reached, and the platform spells it
/// `[i]` appended to the path with no separating dot. Evidence: UT 11.5.27.75
/// `Catalogs/МЧД003/Forms/ДобавлениеПредставителя`, InputField
/// `СвУпПредПредСведИПИННФЛ` carries
/// `{7,{1},{0,e67e2953-…},{2},{0,e67e2953-…},{2,5bdad865-…},{0,e67e2953-…},{5,5bdad865-…}}`
/// and the platform writes `СвУпПред[0].Пред[0].СведИП[0].ИННФЛ`.
const FORM_VALUE_TABLE_INDEX_BINDING_UUID: &str = "e67e2953-cebe-4d97-bb93-12b17e6384f8";

/// The `SettingsComposer` member an object carries in its own right, opening the
/// settings-composer chain from an attribute that is not itself a composer.
///
/// Every one of the 62 chains of UT 11.5.27.75 whose second segment is
/// `{0,b9754f01-…}` is written by the platform with `SettingsComposer` as the
/// path's second component, and no chain writes that component any other way.
/// Without this the whole chain went unresolved and the item fell back to the
/// attribute name alone - `Отчет` - or to the attribute name with the item's own
/// name glued on.
const FORM_OBJECT_SETTINGS_COMPOSER_MEMBER_UUID: &str = "b9754f01-29e9-11d6-a3c7-0050bae0a776";

/// The aggregate marker: a `{101000000,<uuid>}` segment addresses the column
/// total of the member the uuid names rather than the member itself.
const FORM_AGGREGATE_MEMBER_MARKER: &str = "101000000";

/// The row-count marker: a bare `{100000000}` segment addresses the row count
/// of the collection the chain has reached rather than any of its members.
///
/// Evidence: UT 11.5.27.75 writes it only as a chain terminal, on both a
/// two-segment chain over a form collection attribute
/// (`СкидкиНаценки.RowsCount`) and a three-segment chain whose middle segment
/// is a tabular-section reference (`Объект.Товары.RowsCount`). No slot in the
/// configuration uses `100000000` as a declared column id.
const FORM_ROWS_COUNT_MEMBER_MARKER: &str = "100000000";

/// A root metadata reference that is a configuration-wide common attribute
/// contributes its own name and nothing else -- the reference has no owner to
/// route through, so `form_metadata_data_path_route` cannot spell it.
///
/// Evidence: UT 11.5.27.75, all 6 chain segments whose reference is a
/// `CommonAttribute` (`Запись.ОбластьДанныхВспомогательныеДанные`,
/// `Объект.ОбластьДанныхОсновныеДанные`). Every other reference this route
/// refuses is a `Constant`, which the constants-set resolver owns and which
/// must keep falling through.
fn form_common_attribute_member(reference: &str) -> Option<&str> {
    let member = reference.strip_prefix("CommonAttribute.")?;
    (!member.is_empty() && !member.contains('.') && member.trim() == member).then_some(member)
}

/// The standard attributes a chain reaches by dereferencing a tabular section
/// itself, as opposed to dereferencing a value the section holds.
///
/// Evidence: UT 11.5.27.75. On every one of the 320 chains whose next-to-last
/// segment is a tabular-section reference and whose last segment is a negative
/// marker, the marker is `-2` and the platform writes `LineNumber`. The marker
/// alone decides nothing -- `-2` is `Number` under a document object, `Code`
/// under a catalog reference and `Period` under an information-register record
/// manager -- so this table is reached only through the tabular-section role
/// and lists only the marker that role was observed to carry.
const TABULAR_SECTION_STANDARD_ATTRIBUTES: &[(&str, &str)] = &[("-2", "LineNumber")];

fn form_tabular_section_standard_attribute_name(
    reference: &str,
    marker: &str,
) -> Option<&'static str> {
    let path = parse_metadata_data_path(reference)?;
    (path.role() == MetadataDataPathRole::TabularSection)
        .then(|| lookup_form_standard_attribute(TABULAR_SECTION_STANDARD_ATTRIBUTES, marker))?
}

/// Walks a bound slot as the chain it is.
///
/// A bound slot is `{K,s1,…,sK}`: segment 1 names the form attribute the chain
/// starts from and every following segment names one member of whatever the
/// chain has reached so far, the platform writing the join of the per-segment
/// names. Four segment kinds carry a member:
///
/// - `{i,e67e2953-…}` is the row index of the collection reached so far and
///   appends `[i]` with no dot;
/// - `{c,5bdad865-…}` is an *additional* column the attribute declares for the
///   table path reached so far -- the leaf the platform writes for it appears
///   in no other index this parser builds, only in that declaration;
/// - `{c}` is a column the attribute declares outright;
/// - `{m,<uuid>}` is metadata, contributing that member's own leaf name.
///
/// The marker of a metadata segment is normally inert, with one exception:
/// `101000000` is the aggregate marker, and whether the platform writes
/// `Total<member>` or the bare `<member>` is decided not by the slot -- the
/// bytes are identical either way -- but by where the item sits. An item inside
/// the table it addresses reads the row's own column (125 of 125 across UT
/// 11.5.27.75); an item outside it reads the column total (131 of 131). The
/// discriminator is the item's parent path, which the caller supplies.
///
/// Every segment must resolve or the whole chain does, so a slot this walker
/// cannot spell out entirely is left to the other routes untouched. Over all
/// 43 698 slots it does spell out across UT 11.5.27.75, it never disagrees with
/// the platform.
pub(super) fn resolve_form_bound_chain_member_path(
    field: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
    aggregate: bool,
) -> Option<String> {
    let segments = parse_form_bound_chain_segments(field)?;
    let (root, members) = segments.split_first()?;
    let [attribute_id] = root.as_slice() else {
        return None;
    };
    let attribute_id = attribute_id.trim();
    let name = attribute_names_by_id.get(attribute_id)?;
    walk_form_bound_chain_members(
        members,
        attribute_id,
        name.clone(),
        name.clone(),
        owner_scoped_bindings,
        object_refs,
        aggregate,
    )
    .map(|(path, _)| path)
}

/// Walks the member segments of a bound chain whose root has already been read.
///
/// Two paths are carried, because the two are not always the same string. The
/// first is what the platform writes; the second is the same walk spelled in
/// the *attribute's* own namespace, which is what the additional-column
/// declarations are keyed by. They coincide for a chain rooted at an attribute
/// and diverge for one rooted at a form item, whose output prefix is
/// `Items.<table>.CurrentData` while its declarations are still keyed by the
/// table's attribute path.
#[allow(clippy::too_many_arguments)]
fn walk_form_bound_chain_members(
    members: &[Vec<&str>],
    attribute_id: &str,
    mut path: String,
    mut key: String,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
    aggregate: bool,
) -> Option<(String, String)> {
    // The only segment kind that states a type is a declared column, so a
    // dereferencing marker is answered only when it follows one directly.
    let mut reached_type: Option<&str> = None;
    // A metadata reference states which member a chain has reached, and the
    // reference's own role decides which standard attributes the next
    // dereferencing marker may address.
    let mut reached_metadata_reference: Option<&str> = None;
    for segment in members {
        let previous_type = reached_type.take();
        let previous_metadata_reference = reached_metadata_reference.take();
        match segment.as_slice() {
            [index, uuid]
                if uuid
                    .trim()
                    .eq_ignore_ascii_case(FORM_VALUE_TABLE_INDEX_BINDING_UUID) =>
            {
                let index = parse_form_chain_numeric_id(index)?;
                for target in [&mut path, &mut key] {
                    target.push('[');
                    target.push_str(index);
                    target.push(']');
                }
            }
            [column_id, uuid]
                if uuid
                    .trim()
                    .eq_ignore_ascii_case(FORM_VALUE_TABLE_COLUMN_BINDING_UUID) =>
            {
                let lookup = FormAttributeAdditionalColumnKey {
                    attribute_id: attribute_id.to_string(),
                    table_path: form_bound_chain_collection_path(&key),
                    column_id: column_id.trim().to_string(),
                };
                let name = owner_scoped_bindings
                    .additional_columns
                    .get(&lookup)?
                    .as_ref()?;
                for target in [&mut path, &mut key] {
                    target.push('.');
                    target.push_str(name);
                }
            }
            [marker] if marker.trim() == FORM_ROWS_COUNT_MEMBER_MARKER => {
                for target in [&mut path, &mut key] {
                    target.push('.');
                    target.push_str("RowsCount");
                }
            }
            [marker] if marker.trim().starts_with('-') => {
                let name = match previous_type {
                    Some(reference) => {
                        form_standard_attribute_name_for_type_reference(reference, marker.trim())?
                    }
                    None => form_tabular_section_standard_attribute_name(
                        previous_metadata_reference?,
                        marker.trim(),
                    )?,
                };
                for target in [&mut path, &mut key] {
                    target.push('.');
                    target.push_str(name);
                }
            }
            [column_id]
                if previous_type
                    .is_some_and(|reference| form_type_reference_is_standard_period(reference)) =>
            {
                // The built-in standard period the chain has just reached
                // numbers its own three members; they are declared by the type,
                // not by the attribute, so the declared-column index cannot
                // spell them. Evidence: UT 11.5.27.75
                // `DataProcessors/ФормированиеЗаказовНаДоставку/Forms/Форма`,
                // InputField `ПериодОтгрузкиДатаОкончания` carries
                // `{3,{1},{0,e13dd70b-...},{2}}` whose middle segment is the
                // `ПериодОтгрузки` attribute of type `v8:StandardPeriod`, and
                // the platform writes `Объект.ПериодОтгрузки.EndDate`.
                let name = form_standard_period_member_name(column_id.trim())?;
                for target in [&mut path, &mut key] {
                    target.push('.');
                    target.push_str(name);
                }
            }
            [column_id] => {
                let column_id = parse_form_chain_numeric_id(column_id)?;
                let lookup = FormAttributeColumnKey {
                    attribute_id: attribute_id.to_string(),
                    column_id: column_id.to_string(),
                };
                let name = owner_scoped_bindings
                    .declared_columns
                    .get(&lookup)?
                    .as_ref()?;
                for target in [&mut path, &mut key] {
                    target.push('.');
                    target.push_str(name);
                }
                reached_type = owner_scoped_bindings
                    .declared_column_types
                    .get(&lookup)
                    .and_then(|reference| reference.as_deref());
            }
            [marker, uuid] => {
                let marker = marker.trim();
                marker.parse::<i64>().ok()?;
                let uuid = parse_non_zero_uuid(uuid.trim())?;
                let reference = object_refs.get(&uuid)?;
                let Some((_, relative_path)) = form_metadata_data_path_route(reference) else {
                    let member = form_common_attribute_member(reference)?;
                    for target in [&mut path, &mut key] {
                        target.push('.');
                        target.push_str(member);
                    }
                    continue;
                };
                let member = relative_path.rsplit('.').next()?;
                if member.is_empty() {
                    return None;
                }
                path.push('.');
                if aggregate && marker == FORM_AGGREGATE_MEMBER_MARKER {
                    path.push_str("Total");
                }
                path.push_str(member);
                key.push('.');
                key.push_str(member);
                reached_metadata_reference = Some(reference.as_str());
                reached_type = owner_scoped_bindings
                    .metadata_field_types
                    .get(&uuid)
                    .map(String::as_str);
            }
            _ => return None,
        }
    }
    Some((path, key))
}

/// Walks a bound chain whose root is a *form item* rather than a form
/// attribute.
///
/// `{K,{<item>,02023637-…},…}` starts from what the table item shows, which the
/// platform writes `Items.<table>.CurrentData`; every following segment is read
/// exactly as it is on an attribute-rooted chain, because the value the chain
/// stands on is the same value the attribute holds. The two namespaces are kept
/// apart by [`walk_form_bound_chain_members`]: the output carries the
/// `Items.…CurrentData` prefix while the index lookups keep the attribute's own
/// path, which is what the additional-column declarations are keyed by.
///
/// Evidence: UT 11.5.27.75
/// `InformationRegisters/ЗаказыТорговыхПлощадок/Forms/ПросмотрИЗагрузкаЗаказов`,
/// InputField `ТаблицаДанныхЗаказаЦена` carries
/// `{3,{17,02023637-…},{14},{4,5bdad865-…}}` against table item 17
/// (`ТаблицаЗаказов`, bound to attribute 3 of the same name); column 14 is
/// `СписокТоваровВОтправлении` and additional column 4 of the declaration for
/// `ТаблицаЗаказов.СписокТоваровВОтправлении` is `Цена`, and the platform
/// writes `Items.ТаблицаЗаказов.CurrentData.СписокТоваровВОтправлении.Цена`.
/// Keying the additional column by the table item alone cannot tell that
/// declaration from a sibling group that numbers a different column the same,
/// which is what left 12 of those slots unspelled.
fn resolve_form_item_rooted_chain_data_path(
    field: &str,
    table_name_by_id: &BTreeMap<String, String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let (item_id, members) = parse_form_item_rooted_chain(field)?;
    let table_name = table_name_by_id.get(item_id)?;
    let root = owner_scoped_bindings.table_root.get(item_id)?;
    walk_form_bound_chain_members(
        &members,
        &root.attribute_id,
        format!("Items.{table_name}.CurrentData"),
        root.attribute_path.clone(),
        owner_scoped_bindings,
        object_refs,
        false,
    )
    .map(|(path, _)| path)
}

/// The settings-composer members a chain reads past a table item's
/// `CurrentData`.
///
/// The codes are meaningless on their own: `10008` is `ItemFilter` on one
/// collection's row and `Order` on another's. The row type is decided by the
/// table item's *own* binding, so the table's chain is walked first and its
/// terminal collection type names the row table to read; a table whose binding
/// is not a composer chain, or a collection with no row table of its own, is
/// not this route's case and falls through untouched.
fn resolve_form_item_rooted_settings_composer_path(
    field: &str,
    table_name_by_id: &BTreeMap<String, String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
) -> Option<String> {
    let (item_id, members) = parse_form_item_rooted_chain(field)?;
    let table_name = table_name_by_id.get(item_id)?;
    let collection = *owner_scoped_bindings
        .table_settings_composer_type
        .get(item_id)?;
    let mut owner = Some(form_settings_composer_row_type(collection)?);
    let mut path = format!("Items.{table_name}.CurrentData");
    for segment in &members {
        match segment.as_slice() {
            [index, uuid]
                if uuid
                    .trim()
                    .eq_ignore_ascii_case(FORM_VALUE_TABLE_INDEX_BINDING_UUID) =>
            {
                let index = parse_form_chain_numeric_id(index)?;
                path.push('[');
                path.push_str(index);
                path.push(']');
            }
            [member_id] => {
                let (name, next) = form_settings_composer_member(owner?, member_id.trim())?;
                path.push('.');
                path.push_str(name);
                owner = next;
            }
            _ => return None,
        }
    }
    Some(path)
}

/// Splits `{K,{<item>,02023637-…},…}` into the item id and the members that
/// follow it. A chain with no member past the item addresses the row itself,
/// which no route here spells, so it is not accepted.
fn parse_form_item_rooted_chain(field: &str) -> Option<(&str, Vec<Vec<&str>>)> {
    let segments = parse_form_bound_chain_segments(field)?;
    let (root, members) = segments.split_first()?;
    let [item_id, uuid] = root.as_slice() else {
        return None;
    };
    if uuid.trim() != FORM_ITEM_TYPE_UUID || members.is_empty() {
        return None;
    }
    Some((item_id.trim(), members.to_vec()))
}

fn parse_form_chain_numeric_id(field: &str) -> Option<&str> {
    let field = field.trim();
    let value = field.parse::<u64>().ok()?;
    (value.to_string() == field).then_some(field)
}

/// The path an additional-columns declaration is keyed by names the collection
/// itself, so the row indexes a chain accumulates are not part of the key.
fn form_bound_chain_collection_path(path: &str) -> String {
    let mut out = String::with_capacity(path.len());
    let mut rest = path;
    while let Some(open) = rest.find('[') {
        let (head, tail) = rest.split_at(open);
        out.push_str(head);
        let after = &tail[1..];
        match after.find(']') {
            Some(close)
                if close > 0 && after[..close].bytes().all(|byte| byte.is_ascii_digit()) =>
            {
                rest = &after[close + 1..];
            }
            _ => {
                out.push('[');
                rest = after;
            }
        }
    }
    out.push_str(rest);
    out
}

/// The types a settings-composer chain walks through. The numeric ids a
/// composer chain carries are only meaningful against the type reached so far:
/// `1` is `UserSettings` on the composer itself but `Filter` on its settings,
/// and `10002` is `LeftValue` on a filter but `Setting` on a user setting. Each
/// table below lists only the ids its own type was observed to carry.
#[derive(Clone, Copy, Eq, PartialEq)]
enum FormSettingsComposerType {
    SettingsComposer,
    Settings,
    Filter,
    Selection,
    Order,
    ConditionalAppearance,
    UserSettings,
    AvailableFields,
    Appearance,
    Fields,
    GroupFields,
    /// One row of a `Settings` collection shown as a tree: the settings
    /// structure item the table's `CurrentData` stands on.
    SettingsItem,
    /// One row of a `UserSettings` collection shown as a tree.
    UserSettingsItem,
}

/// The row type a table's `CurrentData` stands on, for the collections whose
/// rows a chain walks into. Only the two collections UT 11.5.27.75 shows as a
/// tree are listed; every other composer member refuses rather than guessing a
/// row type.
fn form_settings_composer_row_type(
    collection: FormSettingsComposerType,
) -> Option<FormSettingsComposerType> {
    match collection {
        FormSettingsComposerType::Settings => Some(FormSettingsComposerType::SettingsItem),
        FormSettingsComposerType::UserSettings => Some(FormSettingsComposerType::UserSettingsItem),
        _ => None,
    }
}

/// Evidence: UT 11.5.27.75, all 143 slots rooted at a `dcsset:SettingsComposer`
/// attribute. `Catalogs/ЗакладкиВзаимодействий/Forms/ФормаЭлемента` carries
/// `{3,{2},{0},{1}}` and the platform writes
/// `КомпоновщикНастроек.Settings.Filter`;
/// `SettingsStorages/ХранилищеВариантовОтчетов/Forms/ЭлементУсловногоОформления`
/// carries `{5,{1},{4},{0,e67e2953-…},{10002},{10003}}` and the platform writes
/// `КомпоновщикНастроек.Settings.ConditionalAppearance[0].Filter.ComparisonType`.
fn form_settings_composer_member(
    owner: FormSettingsComposerType,
    member_id: &str,
) -> Option<(&'static str, Option<FormSettingsComposerType>)> {
    use FormSettingsComposerType::*;
    let table: &[(&str, &str, Option<FormSettingsComposerType>)] = match owner {
        SettingsComposer => &[
            ("0", "Settings", Some(Settings)),
            ("1", "UserSettings", Some(UserSettings)),
        ],
        Settings => &[
            ("0", "DataParameters", None),
            ("1", "Filter", Some(Filter)),
            ("2", "Selection", Some(Selection)),
            ("3", "Order", Some(Order)),
            ("4", "ConditionalAppearance", Some(ConditionalAppearance)),
        ],
        Filter => &[
            ("0", "FilterAvailableFields", Some(AvailableFields)),
            ("10000", "Use", None),
            ("10001", "LeftValuePicture", None),
            ("10002", "LeftValue", None),
            ("10003", "ComparisonType", None),
            ("10004", "RightValuePicture", None),
            ("10005", "RightValue", None),
            ("10006", "Date", None),
            ("10007", "GroupType", None),
            ("10008", "Application", None),
            ("10009", "ViewMode", None),
            ("10010", "Presentation", None),
        ],
        Selection => &[("0", "SelectionAvailableFields", Some(AvailableFields))],
        Order => &[
            ("0", "OrderAvailableFields", Some(AvailableFields)),
            ("10000", "Use", None),
            ("10002", "Field", None),
            ("10003", "OrderType", None),
        ],
        ConditionalAppearance => &[
            ("10000", "Use", None),
            ("10001", "Appearance", Some(Appearance)),
            ("10002", "Filter", Some(Filter)),
            ("10003", "Fields", Some(Fields)),
            ("10004", "Presentation", None),
        ],
        UserSettings => &[
            ("10000", "Use", None),
            ("10001", "SettingPicture", None),
            ("10002", "Setting", None),
            ("10003", "ComparisonType", None),
            ("10004", "ValuePicture", None),
            ("10005", "Value", None),
            ("10006", "EditInReportForm", None),
            ("10007", "Filter", Some(Filter)),
        ],
        GroupFields => &[("0", "GroupFieldsAvailableFields", Some(AvailableFields))],
        // Evidence: UT 11.5.27.75, all 13 slots whose owner is a table bound to
        // a `Settings` collection -- `CommonForms/ФормаВариантаОтчета` (12) and
        // `CommonForms/ФормаВыбораДоступногоПоля` (1). The `Item` prefix is the
        // platform's own: the row is one settings item, and its members are
        // named apart from the collection's own like-named members.
        SettingsItem => &[
            ("10007", "ItemDataParameters", None),
            ("10008", "ItemFilter", Some(Filter)),
            ("10009", "ItemGroupFields", Some(GroupFields)),
            ("10010", "ItemSelection", Some(Selection)),
            ("10011", "ItemOrder", Some(Order)),
            (
                "10012",
                "ItemConditionalAppearance",
                Some(ConditionalAppearance),
            ),
            ("10013", "ItemOutputParameters", None),
            ("10014", "ItemUserFields", None),
        ],
        // Evidence: UT 11.5.27.75, all 6 slots whose owner is a table bound to
        // a `UserSettings` collection --
        // `DataProcessors/НастройкаПоддержанияЗапасов/Forms/НастройкаСписка`.
        // The codes are *not* the `Settings` row's codes: `10008` is `ItemFilter`
        // there and `Order` here, so the two tables stay apart and the owner
        // decides which one is read.
        UserSettingsItem => &[
            ("10007", "Filter", Some(Filter)),
            ("10008", "Order", Some(Order)),
            (
                "10010",
                "ConditionalAppearance",
                Some(ConditionalAppearance),
            ),
            ("10011", "Structure", None),
        ],
        AvailableFields => &[("10000", "FieldPicture", None), ("10001", "Title", None)],
        Appearance => &[
            ("10000", "Use", None),
            ("10001", "Parameter", None),
            ("10002", "ValuePicture", None),
            ("10003", "Value", None),
        ],
        // `10001` is the collection's own picture member, the one a table's
        // row picture names. Single observation, UT 11.5.27.75
        // `SettingsStorages/ХранилищеВариантовОтчетов/Forms/ЭлементУсловногоОформленияОтчета`:
        // Table `ОформляемыеПоля` is bound to
        // `КомпоновщикНастроек.Settings.ConditionalAppearance[0].Fields` and
        // its row picture slot holds `{10001}`, written `…Fields.FieldPicture`.
        Fields => &[
            ("10000", "Use", None),
            ("10001", "FieldPicture", None),
            ("10002", "Field", None),
        ],
    };
    table
        .iter()
        .find_map(|(candidate, name, next)| (*candidate == member_id).then_some((*name, *next)))
}

/// The `.Member.Member` tail a chain spells after it has named the settings
/// composer it walks, using the same member table an item's bound slot uses.
fn form_settings_composer_member_walk(members: &[String]) -> Option<String> {
    let mut owner = Some(FormSettingsComposerType::SettingsComposer);
    let mut path = String::new();
    for member in members {
        let (name, next) = form_settings_composer_member(owner?, member.as_str())?;
        path.push('.');
        path.push_str(name);
        owner = next;
    }
    Some(path)
}

pub(super) fn resolve_form_settings_composer_chain_data_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    object_refs: &BTreeMap<String, String>,
    metadata_field_types: &BTreeMap<String, String>,
) -> Option<String> {
    resolve_form_settings_composer_chain(
        field,
        attribute_metadata_owners_by_id,
        object_refs,
        metadata_field_types,
    )
    .map(|(path, _)| path)
}

/// The composer chain plus the type it walked to, for the callers that need to
/// read further members against that type.
fn resolve_form_settings_composer_chain(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    object_refs: &BTreeMap<String, String>,
    metadata_field_types: &BTreeMap<String, String>,
) -> Option<(String, Option<FormSettingsComposerType>)> {
    let segments = parse_form_bound_chain_segments(field)?;
    let (root, members) = segments.split_first()?;
    let [attribute_id] = root.as_slice() else {
        return None;
    };
    let attribute = attribute_metadata_owners_by_id.get(attribute_id.trim())?;
    let mut path = attribute.name.clone();
    let members =
        if attribute.exact_single_type_reference.as_deref() == Some("dcsset:SettingsComposer") {
            members
        } else {
            // The attribute is the object that owns a composer, not the composer
            // itself; the chain names the composer member first and walks on from
            // there.
            let (entry, rest) = members.split_first()?;
            match entry.as_slice() {
                [index, uuid]
                    if index.trim() == "0"
                        && uuid
                            .trim()
                            .eq_ignore_ascii_case(FORM_OBJECT_SETTINGS_COMPOSER_MEMBER_UUID) =>
                {
                    path.push_str(".SettingsComposer");
                }
                // A dynamic list names its own composer by code rather than by the
                // member uuid an object uses. The code is not free: `-6` reads
                // `Parent` on the object attributes that carry one, so it opens the
                // composer only where the attribute really is a dynamic list.
                [code] if code.trim() == "-6" && attribute.has_dynamic_list_settings => {
                    path.push_str(".SettingsComposer");
                }
                // An object can also own a composer as a metadata attribute of
                // its own, and then the chain names that attribute's uuid where
                // the object's built-in member would stand.  The route refused
                // that shape, so the walk stopped at the form attribute and the
                // export named the attribute alone.
                //
                // Two independent facts have to line up before a segment is read
                // this way, so a plain metadata member of any other type still
                // fails closed: the uuid has to resolve to a member of the very
                // object the form attribute is typed as -- the same match the
                // saved-field walk requires -- and that member's *declared* type
                // has to be the settings composer itself.
                //
                // Evidence: UT 11.5.27.75,
                // `DataProcessors/СверкаПродажЛьготныхТоваровОплаченныхЭСФСС/Forms/Форма`.
                // Its two settings tables bind `{3,{1},{0,f69186c1-…},{1}}` and
                // `{3,{1},{0,3fcc6fc5-…},{0}}`, which the platform writes
                // `Объект.КомпоновщикНастроекОтбор.UserSettings` and
                // `Объект.КомпоновщикНастроекОтчет.Settings`; the route refused
                // both, and every column under those two tables fell back to
                // naming the form attribute alone.
                [index, uuid] if index.trim() == "0" && !rest.is_empty() => {
                    let uuid = parse_non_zero_uuid(uuid.trim())?;
                    if metadata_field_types.get(&uuid).map(String::as_str)
                        != Some("dcsset:SettingsComposer")
                    {
                        return None;
                    }
                    let reference = object_refs.get(&uuid)?;
                    let (owner_base, relative_path) = form_metadata_data_path_route(reference)?;
                    if !form_attribute_matches_metadata_owner(attribute, &owner_base) {
                        return None;
                    }
                    path.push('.');
                    path.push_str(&relative_path);
                }
                _ => return None,
            }
            rest
        };
    let mut owner = Some(FormSettingsComposerType::SettingsComposer);
    for segment in members {
        match segment.as_slice() {
            [index, uuid]
                if uuid
                    .trim()
                    .eq_ignore_ascii_case(FORM_VALUE_TABLE_INDEX_BINDING_UUID) =>
            {
                let index = parse_form_chain_numeric_id(index)?;
                path.push('[');
                path.push_str(index);
                path.push(']');
            }
            [member_id] => {
                let (name, next) = form_settings_composer_member(owner?, member_id.trim())?;
                path.push('.');
                path.push_str(name);
                owner = next;
            }
            _ => return None,
        }
    }
    Some((path, owner))
}

/// The members a dynamic list carries in its own right, numbered by negative
/// codes so they cannot be confused with the list's own fields.
///
/// `-6` is the list's settings composer, already read by the composer chain.
/// Evidence for the two below, UT 11.5.27.75:
/// `InformationRegisters/ОбработчикиОбновления/Forms/ФормаСписка` InputField
/// `Порядок` carries `{2,{1},{-1}}` against the `Список` dynamic list and is
/// written `Список.Order`;
/// `DataProcessors/СервисSellmonitor/Forms/ПодборКарточекТоваров` Table
/// `СписокМаркетплейсOzonОтбор` carries `{2,{2},{-2}}` and is written
/// `СписокМаркетплейсOzon.Filter`. Both are the only paths of their shape in
/// the configuration; every other negative code on a dynamic list stays
/// unresolved rather than guessed.
fn resolve_form_dynamic_list_member_data_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let [kind, owner, terminal] = fields.as_slice() else {
        return None;
    };
    if kind.trim() != "2" {
        return None;
    }
    let owner = split_1c_braced_fields(owner.trim(), 0)?;
    let terminal = split_1c_braced_fields(terminal.trim(), 0)?;
    let ([attribute_id], [marker]) = (owner.as_slice(), terminal.as_slice()) else {
        return None;
    };
    let attribute = attribute_metadata_owners_by_id.get(attribute_id.trim())?;
    if !attribute.has_dynamic_list_settings {
        return None;
    }
    let name = match marker.trim() {
        "-1" => "Order",
        "-2" => "Filter",
        _ => return None,
    };
    Some(format!("{}.{name}", attribute.name))
}

fn form_type_reference_is_standard_period(reference: &str) -> bool {
    matches!(reference, "v8:StandardPeriod" | "StandardPeriod")
}

/// The three members the built-in standard period declares, by the id a bound
/// chain numbers them with. Same table the attribute-rooted route reads.
fn form_standard_period_member_name(column_id: &str) -> Option<&'static str> {
    match column_id {
        "0" => Some("Variant"),
        "1" => Some("StartDate"),
        "2" => Some("EndDate"),
        _ => None,
    }
}

/// The built-in standard period's own columns. `1` and `2` are already reached
/// through the special-column index; `0` is not, and the platform writes
/// `Variant` for it in all 9 slots UT 11.5.27.75 spells out.
pub(super) fn resolve_form_standard_period_column_data_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let [kind, owner, terminal] = fields.as_slice() else {
        return None;
    };
    if kind.trim() != "2" {
        return None;
    }
    let owner = split_1c_braced_fields(owner.trim(), 0)?;
    let terminal = split_1c_braced_fields(terminal.trim(), 0)?;
    let ([attribute_id], [column_id]) = (owner.as_slice(), terminal.as_slice()) else {
        return None;
    };
    let attribute = attribute_metadata_owners_by_id.get(attribute_id.trim())?;
    if attribute.exact_single_type_reference.as_deref() != Some("v8:StandardPeriod") {
        return None;
    }
    let name = match column_id.trim() {
        "0" => "Variant",
        "1" => "StartDate",
        "2" => "EndDate",
        _ => return None,
    };
    Some(format!("{}.{}", attribute.name, name))
}

fn resolve_form_attribute_column_data_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
) -> FormOwnerScopedDataPath {
    let Some(fields) = split_1c_braced_fields(field.trim(), 0) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    let [kind, owner, column] = fields.as_slice() else {
        return FormOwnerScopedDataPath::Unknown;
    };
    if kind.trim() != "2" {
        return FormOwnerScopedDataPath::Unknown;
    }
    let Some(owner) = split_1c_braced_fields(owner.trim(), 0) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    let Some(column) = split_1c_braced_fields(column.trim(), 0) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    if owner.len() != 1 || column.len() != 1 {
        return FormOwnerScopedDataPath::Unknown;
    }
    let attribute_id = owner[0].trim();
    let column_id = column[0].trim();
    let Ok(column_number) = column_id.parse::<u64>() else {
        return FormOwnerScopedDataPath::Unknown;
    };
    if column_number.to_string() != column_id {
        return FormOwnerScopedDataPath::Unknown;
    }
    // A zero column id only names a column on the built-in value list, whose
    // `Value` column the platform numbers `0`; anywhere else it is not evidence
    // of a bound column.
    if column_number == 0
        && !owner_scoped_bindings
            .value_list_attribute_ids
            .contains(attribute_id)
    {
        return FormOwnerScopedDataPath::Unknown;
    }
    let key = FormAttributeColumnKey {
        attribute_id: attribute_id.to_string(),
        column_id: column_id.to_string(),
    };
    let Some(column_name) = owner_scoped_bindings.attribute_columns.get(&key) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    let Some(column_name) = column_name else {
        return FormOwnerScopedDataPath::Ambiguous;
    };
    let Some(attribute) = attribute_metadata_owners_by_id.get(attribute_id) else {
        return FormOwnerScopedDataPath::Unknown;
    };
    // A field the list cannot resolve against its data source is written with
    // the platform's own `~` marker, exactly as `<UseAlways>` writes it.
    // Evidence: UT 11.5.27.75
    // `InformationRegisters/НастройкиОбменаЕИСДляЗаказчиков/Forms/ФормаСписка`,
    // LabelField `РегистрационныйНомерЕРУЗ` carries `{2,{1},{16}}` and is
    // written `~Список.РегистрационныйНомерЕРУЗ`, while the same field name
    // under a list that does resolve it is written without the marker.
    let marker = if owner_scoped_bindings.unresolvable_columns.contains(&key) {
        "~"
    } else {
        ""
    };
    FormOwnerScopedDataPath::Resolved(format!("{marker}{}.{}", attribute.name, column_name))
}

fn parse_form_bound_data_path_with_metadata_owner(
    field: &str,
    name: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    bound_table_path_by_binding_key: &BTreeMap<String, String>,
    table_column_names_by_binding_key: &BTreeMap<String, BTreeMap<String, String>>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    match resolve_form_owner_scoped_metadata_data_path_status(
        field,
        attribute_metadata_owners_by_id,
        object_refs,
    ) {
        FormMetadataDataPathResolution::Resolved(data_path) => Some(data_path),
        FormMetadataDataPathResolution::NotMetadata
        | FormMetadataDataPathResolution::ReferenceAbsent => parse_form_bound_data_path(
            field,
            name,
            attribute_names_by_id,
            table_name_by_id,
            table_column_names_by_id,
            bound_table_path_by_binding_key,
            table_column_names_by_binding_key,
        ),
        FormMetadataDataPathResolution::Invalid | FormMetadataDataPathResolution::ForeignOwner => {
            None
        }
    }
}

#[cfg(test)]
pub(super) fn resolve_form_owner_scoped_metadata_data_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    match resolve_form_owner_scoped_metadata_data_path_status(
        field,
        attribute_metadata_owners_by_id,
        object_refs,
    ) {
        FormMetadataDataPathResolution::Resolved(data_path) => Some(data_path),
        FormMetadataDataPathResolution::NotMetadata
        | FormMetadataDataPathResolution::ReferenceAbsent
        | FormMetadataDataPathResolution::Invalid
        | FormMetadataDataPathResolution::ForeignOwner => None,
    }
}

enum FormMetadataDataPathResolution {
    NotMetadata,
    ReferenceAbsent,
    Invalid,
    /// The terminal names metadata of a type the owner attribute is not. On a
    /// two-segment binding that is a contradiction, but on a longer chain it is
    /// the ordinary case: the terminal belongs to the type an *intermediate*
    /// segment reaches, not to the attribute the chain starts from.
    ForeignOwner,
    Resolved(String),
}

fn resolve_form_owner_scoped_metadata_data_path_status(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    object_refs: &BTreeMap<String, String>,
) -> FormMetadataDataPathResolution {
    let Some(fields) = split_1c_braced_fields(field.trim(), 0) else {
        return FormMetadataDataPathResolution::Invalid;
    };
    let (owner_field, terminal_field) = match fields.as_slice() {
        [kind, owner, terminal] if kind.trim() == "2" => (*owner, *terminal),
        [kind, owner, table, terminal]
            if kind.trim() == "3" && parse_form_binding_key(table.trim()).is_some() =>
        {
            (*owner, *terminal)
        }
        _ => return FormMetadataDataPathResolution::NotMetadata,
    };
    let Some(terminal) = split_1c_braced_fields(terminal_field.trim(), 0) else {
        return FormMetadataDataPathResolution::Invalid;
    };
    if terminal.len() != 2 {
        return FormMetadataDataPathResolution::NotMetadata;
    }
    let Some(marker) = terminal.first() else {
        return FormMetadataDataPathResolution::Invalid;
    };
    if marker.trim().parse::<i64>().is_err() {
        return FormMetadataDataPathResolution::Invalid;
    }
    let Some(uuid) = terminal
        .get(1)
        .and_then(|uuid| parse_non_zero_uuid(uuid.trim()))
    else {
        return FormMetadataDataPathResolution::Invalid;
    };

    let Some(owner) = split_1c_braced_fields(owner_field.trim(), 0) else {
        return FormMetadataDataPathResolution::Invalid;
    };
    // A `{id,02023637-…}` owner names a *form item*, not a form attribute, so
    // the binding is not owner-scoped metadata at all and must be left for the
    // item-scoped resolver rather than condemned as a broken attribute route.
    if owner.len() == 2 && owner.get(1).map(|field| field.trim()) == Some(FORM_ITEM_TYPE_UUID) {
        return FormMetadataDataPathResolution::NotMetadata;
    }
    if owner.len() != 1 {
        return FormMetadataDataPathResolution::Invalid;
    }
    let Some(attribute_id) = owner.first() else {
        return FormMetadataDataPathResolution::Invalid;
    };
    resolve_form_owner_scoped_metadata_uuid_data_path_status(
        attribute_id.trim(),
        marker.trim(),
        &uuid,
        attribute_metadata_owners_by_id,
        object_refs,
    )
}

fn resolve_form_owner_scoped_metadata_uuid_data_path_status(
    attribute_id: &str,
    marker: &str,
    uuid: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    object_refs: &BTreeMap<String, String>,
) -> FormMetadataDataPathResolution {
    if marker.parse::<i64>().is_err() {
        return FormMetadataDataPathResolution::Invalid;
    }
    let Some(uuid) = parse_non_zero_uuid(uuid) else {
        return FormMetadataDataPathResolution::Invalid;
    };
    let Some(attribute) = attribute_metadata_owners_by_id.get(attribute_id.trim()) else {
        return FormMetadataDataPathResolution::Invalid;
    };

    let Some(reference) = object_refs.get(&uuid) else {
        return FormMetadataDataPathResolution::ReferenceAbsent;
    };
    let Some((owner_base, relative_path)) = form_metadata_data_path_route(reference) else {
        return FormMetadataDataPathResolution::Invalid;
    };
    if !form_attribute_matches_metadata_owner(attribute, &owner_base) {
        return FormMetadataDataPathResolution::ForeignOwner;
    }
    FormMetadataDataPathResolution::Resolved(format!("{}.{}", attribute.name, relative_path))
}

pub(super) fn resolve_form_strict_field_model_data_path(
    field: &str,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let [kind, owner, terminal] = fields.as_slice() else {
        return None;
    };
    if kind.trim() != "2" {
        return None;
    }
    let owner = split_1c_braced_fields(owner.trim(), 0)?;
    if owner.len() != 1 {
        return None;
    }
    let attribute = attribute_metadata_owners_by_id.get(owner.first()?.trim())?;
    let terminal = split_1c_braced_fields(terminal.trim(), 0)?;
    match terminal.as_slice() {
        [marker] => {
            let marker = marker.trim();
            marker.parse::<i64>().ok()?;
            resolve_form_owner_scoped_standard_attribute_data_path(attribute, marker)
        }
        [marker, uuid] => {
            marker.trim().parse::<i64>().ok()?;
            let uuid = parse_non_zero_uuid(uuid.trim())?;
            let reference = object_refs.get(&uuid)?;
            resolve_form_constants_set_data_path(attribute, reference)
        }
        _ => None,
    }
}

pub(super) fn resolve_form_owner_scoped_standard_attribute_data_path(
    attribute: &FormAttributeMetadataOwner,
    marker: &str,
) -> Option<String> {
    let reference = attribute.exact_single_type_reference.as_deref()?;
    let attribute_name = form_standard_attribute_name_for_type_reference(reference, marker)?;
    Some(format!("{}.{}", attribute.name, attribute_name))
}

fn form_standard_attribute_name_for_type_reference(
    reference: &str,
    marker: &str,
) -> Option<&'static str> {
    let owner = form_generated_owner_type_from_type_reference(reference)?;
    match (owner.family(), owner.role()) {
        (GeneratedMetadataOwnerFamily::Document, GeneratedMetadataOwnerRole::Object) => {
            DOCUMENT_STANDARD_ATTRIBUTES
                .iter()
                .find_map(|(candidate, name)| (*candidate == marker).then_some(*name))
        }
        (GeneratedMetadataOwnerFamily::ChartOfAccounts, GeneratedMetadataOwnerRole::Object) => {
            chart_of_accounts_standard_attribute_name(marker)
        }
        (GeneratedMetadataOwnerFamily::BusinessProcess, GeneratedMetadataOwnerRole::Object) => {
            BUSINESS_PROCESS_STANDARD_ATTRIBUTES
                .iter()
                .find_map(|(candidate, name)| (*candidate == marker).then_some(*name))
        }
        (GeneratedMetadataOwnerFamily::Catalog, GeneratedMetadataOwnerRole::Object) => {
            lookup_form_standard_attribute(CATALOG_OBJECT_STANDARD_ATTRIBUTES, marker)
        }
        (GeneratedMetadataOwnerFamily::Catalog, GeneratedMetadataOwnerRole::Ref) => {
            lookup_form_standard_attribute(CATALOG_REF_STANDARD_ATTRIBUTES, marker)
        }
        (GeneratedMetadataOwnerFamily::Task, GeneratedMetadataOwnerRole::Object) => {
            lookup_form_standard_attribute(TASK_OBJECT_STANDARD_ATTRIBUTES, marker)
        }
        (
            GeneratedMetadataOwnerFamily::ChartOfCharacteristicTypes,
            GeneratedMetadataOwnerRole::Object,
        ) => lookup_form_standard_attribute(
            CHART_OF_CHARACTERISTIC_TYPES_OBJECT_STANDARD_ATTRIBUTES,
            marker,
        ),
        (GeneratedMetadataOwnerFamily::ExchangePlan, GeneratedMetadataOwnerRole::Object) => {
            lookup_form_standard_attribute(EXCHANGE_PLAN_OBJECT_STANDARD_ATTRIBUTES, marker)
        }
        (
            GeneratedMetadataOwnerFamily::InformationRegister,
            GeneratedMetadataOwnerRole::RecordManager | GeneratedMetadataOwnerRole::RecordSet,
        ) => lookup_form_standard_attribute(INFORMATION_REGISTER_STANDARD_ATTRIBUTES, marker),
        (GeneratedMetadataOwnerFamily::Document, GeneratedMetadataOwnerRole::Ref) => {
            lookup_form_standard_attribute(DOCUMENT_REF_STANDARD_ATTRIBUTES, marker)
        }
        _ => None,
    }
}

fn lookup_form_standard_attribute(
    table: &[(&str, &'static str)],
    marker: &str,
) -> Option<&'static str> {
    table
        .iter()
        .find_map(|(candidate, name)| (*candidate == marker).then_some(*name))
}

/// Standard attributes a bound field slot reaches through a
/// `{2,{attribute},{marker}}` binding, one table per generated owner type.
///
/// Evidence: UT 11.5.27.75. Over the 1 395 such slots the whole configuration
/// spells out, `(generated owner type, marker)` determines the name the
/// platform writes with no exception -- 317 `cfg:CatalogObject`/`-3` all
/// `Description`, 316 `cfg:DocumentObject`/`-2` all `Number`, 89
/// `cfg:CatalogObject`/`-4` all `Parent`, 43 `cfg:CatalogObject`/`-5` all
/// `Owner`, and so on down to the singletons. The marker alone does not
/// determine it -- `-2` is `Number` under `cfg:DocumentObject`, `Code` under
/// `cfg:CatalogObject` and `Period` under `cfg:InformationRegisterRecordManager`
/// -- so a family-blind table would be a guess, and each table below lists only
/// the markers its own family was observed to carry.
const CATALOG_OBJECT_STANDARD_ATTRIBUTES: &[(&str, &str)] = &[
    ("-2", "Code"),
    ("-3", "Description"),
    ("-4", "Parent"),
    ("-5", "Owner"),
    ("-8", "Ref"),
];
/// Reached by dereferencing a value whose declared type is exactly one catalog
/// reference, whether that value is a form column or a metadata field.
///
/// `-5` joined the table when metadata fields started reaching it. Evidence:
/// UT 11.5.27.75, the 7 forms whose chain reaches
/// `Объект.ПодарочныеСертификаты.ПодарочныйСертификат` -- a field declared
/// `cfg:CatalogRef.ПодарочныеСертификаты` -- and then carries `{-5}`; the
/// platform writes `Owner` on every one, and writes no other standard attribute
/// under that prefix. The same marker is `Owner` under `cfg:CatalogObject` too,
/// and this is the only role a catalog reference was observed to carry it in.
const CATALOG_REF_STANDARD_ATTRIBUTES: &[(&str, &str)] =
    &[("-2", "Code"), ("-3", "Description"), ("-5", "Owner")];
const TASK_OBJECT_STANDARD_ATTRIBUTES: &[(&str, &str)] = &[
    ("-2", "Number"),
    ("-3", "Date"),
    ("-5", "Ref"),
    ("-7", "BusinessProcess"),
    ("-8", "RoutePoint"),
    ("-9", "Description"),
    ("-10", "Executed"),
];
/// `-2` and `-5` joined the table when the generalized choice-parameter-link
/// terminal started reaching them. Evidence: UT 11.5.27.75,
/// `ChartsOfCharacteristicTypes/СтатьиРасходов/Forms/ФормаЭлемента`, whose two
/// `ChoiceParameterLinks` collections spell `"Предопределенный",2,{1},{-5}` and
/// `"Ссылка",2,{1},{-2}` against attribute `Объект` of exact type
/// `cfg:ChartOfCharacteristicTypesObject.СтатьиРасходов`; the platform writes
/// `Объект.Predefined` and `Объект.Ref`, four of each. Those eight terminals are
/// the only `-2`/`-5` this family carries anywhere in the configuration, so the
/// two rows are exactly as wide as their evidence -- and note `-5` is `Owner`
/// under a catalog object and `Predefined` here, which is why the marker cannot
/// be read family-blind.
const CHART_OF_CHARACTERISTIC_TYPES_OBJECT_STANDARD_ATTRIBUTES: &[(&str, &str)] = &[
    ("-2", "Ref"),
    ("-5", "Predefined"),
    ("-6", "Parent"),
    ("-8", "Code"),
    ("-9", "Description"),
    ("-11", "ValueType"),
];
const EXCHANGE_PLAN_OBJECT_STANDARD_ATTRIBUTES: &[(&str, &str)] = &[
    ("-2", "Code"),
    ("-3", "Description"),
    ("-6", "Ref"),
    ("-9", "SentNo"),
    ("-10", "ReceivedNo"),
    ("-14", "ExchangeDate"),
];
const INFORMATION_REGISTER_STANDARD_ATTRIBUTES: &[(&str, &str)] = &[("-2", "Period")];
/// Reached only by dereferencing a *column* whose declared type is exactly one
/// document reference. Evidence: UT 11.5.27.75
/// `Documents/ЗаказПоставщику/Forms/СозданиеЗаказовПоставщикамНаОсновании`,
/// InputField `ЗаказыНомер` carries `{3,{5},{1},{-2}}` where column `1` of
/// attribute `Заказы` is `Ссылка` of type `cfg:DocumentRef.ЗаказПоставщику`, and
/// the platform writes `Заказы.Ссылка.Number`; `ЗаказыДата` carries `{-3}` in
/// the same place and writes `Заказы.Ссылка.Date`.
const DOCUMENT_REF_STANDARD_ATTRIBUTES: &[(&str, &str)] = &[("-2", "Number"), ("-3", "Date")];

/// Business-process standard attributes reachable through a bound field slot,
/// limited to the markers the platform bytes actually spell out.
///
/// Evidence: UT 11.5.27.75
/// `BusinessProcesses/СогласованиеЗакупки/Forms/ФормаБизнесПроцесса`, where
/// InputField `Дата` carries `{2,{1},{-3}}` and InputField `Номер` carries
/// `{2,{1},{-2}}` against the `Объект` attribute, and the platform writes
/// `<DataPath>Объект.Date</DataPath>` and `<DataPath>Объект.Number</DataPath>`.
/// The remaining business-process standard attributes are deliberately absent:
/// no observed slot names them, and the document marker table is not evidence
/// for a different family.
const BUSINESS_PROCESS_STANDARD_ATTRIBUTES: [(&str, &str); 2] = [("-3", "Date"), ("-2", "Number")];

fn resolve_form_constants_set_data_path(
    attribute: &FormAttributeMetadataOwner,
    reference: &str,
) -> Option<String> {
    if attribute.exact_single_type_reference.as_deref() != Some("cfg:ConstantsSet") {
        return None;
    }
    let (kind, constant_name) = reference.split_once('.')?;
    if kind != "Constant" || constant_name.is_empty() || constant_name.contains('.') {
        return None;
    }
    Some(format!("{}.{}", attribute.name, constant_name))
}

/// Resolves a table-current-data choice link whose column is addressed by the
/// metadata UUID of the member it displays, rather than by a form binding id.
///
/// The route table is built from bindings the layout states outright, so it
/// has no entry when the link names the member itself. What the platform
/// writes in that case is the table element's own name joined to the member's
/// own name -- not the member's owner, which need not be the table's:
/// `Documents/ВводОстатковТоваров/Forms/ФормаТовары` addresses
/// `Document.ВводОстатковТоваров.TabularSection.Товары.Attribute.Характеристика`
/// from a table named `ПереданныеПереработчикамТовары` and the export reads
/// `Items.ПереданныеПереработчикамТовары.CurrentData.Характеристика`. The same
/// join holds for a register dimension: `Catalogs/Новости/Forms/ФормаДокумента`
/// addresses `InformationRegister.КатегорииНовостейПростые.Dimension.
/// КатегорияНовостей` from a table named `КатегорииПростые` and exports
/// `Items.КатегорииПростые.CurrentData.КатегорияНовостей`.
///
/// So the owner is deliberately not required to match: it is the member's
/// leaf name that the column carries. A UUID that resolves to no metadata
/// member, or to a reference with no member name, still fails closed.
fn resolve_form_table_current_data_metadata_uuid_path(
    table_id: &str,
    uuid: &str,
    table_name_by_id: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let table_name = table_name_by_id.get(table_id)?;
    let uuid = parse_non_zero_uuid(uuid)?;
    let reference = object_refs.get(&uuid)?;
    let (_, relative_path) = form_metadata_data_path_route(reference)?;
    let member = relative_path.rsplit('.').next()?;
    if member.is_empty() {
        return None;
    }
    Some(format!(
        "Items.{table_name}.CurrentData.{}",
        normalize_form_table_column_name(table_name, member)
    ))
}

/// A task's addressing attributes are members of the task exactly as its
/// ordinary attributes are, and the platform writes them by their own name.
/// The shared metadata-path grammar has no `AddressingAttribute` role, so the
/// reference is recognised here, restricted to the one family that owns such
/// members. Evidence: UT 11.5.27.75
/// `BusinessProcesses/СогласованиеЗакупки/Forms/ФормаЗадачиРецензента`,
/// LabelField `Исполнитель` carries `{2,{1},{0,88f44c9b-…}}` against attribute
/// `Объект` of type `cfg:TaskObject.ЗадачаИсполнителя`, the uuid resolves to
/// `Task.ЗадачаИсполнителя.AddressingAttribute.Исполнитель`, and the platform
/// writes `<DataPath>Объект.Исполнитель</DataPath>`.
fn form_task_addressing_attribute_route(reference: &str) -> Option<(String, String)> {
    let parts = reference.split('.').collect::<Vec<_>>();
    let [family, owner, role, member] = parts.as_slice() else {
        return None;
    };
    if *family != "Task" || *role != "AddressingAttribute" {
        return None;
    }
    if owner.is_empty() || member.is_empty() {
        return None;
    }
    Some((format!("{family}.{owner}"), (*member).to_string()))
}

pub(super) fn form_metadata_data_path_route(reference: &str) -> Option<(String, String)> {
    if let Some(route) = form_task_addressing_attribute_route(reference) {
        return Some(route);
    }
    let path = parse_metadata_data_path(reference)?;
    let relative_path = match path.role() {
        MetadataDataPathRole::Attribute
        | MetadataDataPathRole::Dimension
        | MetadataDataPathRole::Resource => path.member_name().to_string(),
        MetadataDataPathRole::TabularSection => path.table_name()?.to_string(),
        MetadataDataPathRole::TabularAttribute => {
            format!("{}.{}", path.table_name()?, path.member_name())
        }
    };
    Some((path.owner_reference(), relative_path))
}

fn form_attribute_matches_metadata_owner(
    attribute: &FormAttributeMetadataOwner,
    owner_base: &str,
) -> bool {
    let mut proven_bases = attribute
        .type_references
        .iter()
        .filter_map(|reference| form_metadata_owner_base_from_type_reference(reference))
        .collect::<BTreeSet<_>>();
    if let Some(main_table) = attribute.main_table.as_ref() {
        proven_bases.insert(main_table.clone());
    }
    proven_bases.len() == 1 && proven_bases.contains(owner_base)
}

/// The bound title of a `Page` or a `UsualGroup`.
///
/// A conditional prefix does not move the options bag and does not change what
/// the binding means: over all 33 694 native `Page`/`UsualGroup` items of
/// UT 11.5.27.75 the walker reproduces the platform's `<TitleDataPath>` on
/// every one of the 75 items whose layout carries such a prefix -- writing the
/// element on the 8 that have one and nothing on the other 67 -- as well as on
/// every item without one. Refusing the whole slot when the prefix is present
/// is what hid those eight.
pub(super) fn parse_form_title_data_path(
    tag: &str,
    wrapper: &str,
    fields: &[&str],
    attribute_names_by_id: &BTreeMap<String, String>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    if wrapper != "22" {
        return None;
    }
    // The bound slot is the same chain grammar every other bound slot uses, so
    // the title reads it with the same walker. What identifies the slot is the
    // options bag's own shape -- kind and length -- and not the item's raw
    // field count, which varies from 30 to 42 across the 427 title-bound items
    // the configuration spells out without changing where the binding sits.
    let (options_kind, options_len, binding_slot) = match tag {
        "Page" => ("18", 20, 4),
        "UsualGroup" => ("29", 29, 5),
        _ => return None,
    };
    let options = fields
        .get(20)
        .and_then(|field| split_1c_braced_fields(field.trim(), 0))?;
    if options.len() != options_len
        || options.first().map(|field| field.trim()) != Some(options_kind)
    {
        return None;
    }
    let binding = options.get(binding_slot)?.trim();
    if let Some(path) = resolve_form_bound_chain_member_path(
        binding,
        attribute_names_by_id,
        owner_scoped_bindings,
        object_refs,
        false,
    ) {
        return Some(path);
    }
    // A chain rooted at a form item is read by the one route every other bound
    // slot reads it with, against the table-column routes the form itself
    // states. Reading it here through the *global* binding-key index instead
    // answered a column id with whatever name some unrelated item had inferred
    // for that same id: on two catalog list forms of UT 11.5.27.75 the column
    // the group's title binds to is named `Description` by the list's own field
    // map, and the global index answered the caption of a label field instead.
    resolve_form_item_scoped_current_data_path(
        binding,
        table_name_by_id,
        table_column_names_by_id,
        type_link_data_path_by_table_column,
        object_refs,
        owner_scoped_bindings,
    )
}

pub(super) fn form_metadata_owner_base_from_type_reference(reference: &str) -> Option<String> {
    Some(form_generated_owner_type_from_type_reference(reference)?.owner_reference())
}

fn form_generated_owner_type_from_type_reference(
    reference: &str,
) -> Option<GeneratedMetadataOwner<'_>> {
    parse_generated_metadata_owner(reference)
}

pub(super) fn parse_form_bound_data_path(
    field: &str,
    name: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    bound_table_path_by_binding_key: &BTreeMap<String, String>,
    table_column_names_by_binding_key: &BTreeMap<String, BTreeMap<String, String>>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    match fields.first().map(|value| value.trim()) {
        Some("1") => parse_form_attribute_data_path(field, name, attribute_names_by_id),
        Some("2") => {
            let table = fields
                .get(1)
                .and_then(|field| split_1c_braced_fields(field, 0))?;
            let table_id = table.first()?.trim();
            let table_name = attribute_names_by_id
                .get(table_id)
                .or_else(|| table_name_by_id.get(table_id))?;
            let column = parse_form_binding_key(fields.get(2)?.trim())?;
            if let Some(table_path) = bound_table_path_by_binding_key.get(&column) {
                return Some(table_path.clone());
            }
            let field_name = table_column_names_by_id
                .get(table_id)
                .and_then(|columns| columns.get(&column))
                .cloned()
                .or_else(|| (column == "8").then(|| "Ссылка".to_string()))?;
            let field_name = normalize_form_table_column_name(table_name, &field_name);
            Some(format!("{table_name}.{field_name}"))
        }
        Some("3") => {
            let table_key = parse_form_binding_key(fields.get(2)?.trim())?;
            let table_path = bound_table_path_by_binding_key.get(&table_key)?;
            let column_key = parse_form_binding_key(fields.get(3)?.trim())?;
            let field_name = table_column_names_by_binding_key
                .get(&table_key)
                .and_then(|columns| columns.get(&column_key))
                .cloned()
                .or_else(|| (column_key == "8").then(|| "Ссылка".to_string()))?;
            let field_name = normalize_form_table_column_name(table_path, &field_name);
            Some(format!("{table_path}.{field_name}"))
        }
        _ => None,
    }
}

/// Whether a dynamic list's `DefaultPicture` sits outside the table the list
/// declares, which the platform marks by prefixing the whole path with `~`.
///
/// Evidence: UT 11.5.27.75 spells out 1 587 `…DefaultPicture` row-picture
/// paths. All 55 whose list declares no main table carry `~`, and so do all 6
/// whose declared main table is an `Enum` -- an enumeration has no default
/// picture of its own, so the field cannot come from that table. Every one of
/// the remaining 1 526, over nine other main-table families, carries no `~`.
pub(super) fn form_dynamic_list_default_picture_is_out_of_main_table(
    attribute: &FormAttributeMetadataOwner,
) -> bool {
    if !attribute.has_dynamic_list_settings {
        return false;
    }
    match attribute.main_table.as_deref() {
        None => true,
        Some(main_table) => main_table
            .split_once('.')
            .is_some_and(|(family, _)| family == "Enum"),
    }
}

/// The row picture of a table, whose slot holds one member of whatever the
/// table's own bound chain has reached.
///
/// Three of the four payload shapes name the member outright and are spelled
/// against the table's resolved path. The fourth -- `{c,5bdad865-…}` -- is the
/// additional-column segment of the one bound-chain grammar, and it is spelled
/// by appending it to the table's own binding and handing the result to the
/// chain walker, so the row picture reads exactly the grammar every other bound
/// slot reads instead of a second, private table.
///
/// Evidence: UT 11.5.27.75 writes the property on 2 203 of its 4 543 tables.
/// The additional-column shape accounts for 20 of them, on none of which the
/// old reader produced anything, and the appended chain reproduces the
/// platform's path on every one it resolves. The shape never occurs on a table
/// that carries no row picture.
/// One member appended to a table's own bound chain, resolved through the very
/// walkers the data-path slot resolves that chain with.
///
/// The row picture names a member of what the table's chain reached, so it has
/// no grammar of its own. Reading it with only the attribute-rooted walker left
/// three shapes unspelled that the data-path slot of the very same tables
/// reads: an item-rooted chain
/// (`DataProcessors/ИнтеграцияС1СДокументооборот/Forms/АдреснаяКнига`, Table
/// `АдресатыАдреса`, written
/// `Items.Адресаты.CurrentData.Адреса.Картинка`), a settings-composer chain
/// (`SettingsStorages/ХранилищеВариантовОтчетов/Forms/ЭлементУсловногоОформленияОтчета`,
/// Table `ОформляемыеПоля`, written
/// `КомпоновщикНастроек.Settings.ConditionalAppearance[0].Fields.FieldPicture`)
/// and a plain declared column the row-picture index does not carry
/// (`DataProcessors/УправлениеПродажамиНаOzon/Forms/НастройкиПринадлежностиТоваровСхемамРаботы`,
/// Table `СписокКатегорийОтбора`, written `СписокКатегорийОтбора.Check`).
#[allow(clippy::too_many_arguments)]
fn resolve_form_table_row_picture_member(
    binding: &str,
    segment: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let extended = form_bound_chain_with_extra_segment(binding, segment)?;
    resolve_form_settings_composer_chain_data_path(
        &extended,
        attribute_metadata_owners_by_id,
        object_refs,
        &owner_scoped_bindings.metadata_field_types,
    )
    .or_else(|| {
        resolve_form_bound_chain_member_path(
            &extended,
            attribute_names_by_id,
            owner_scoped_bindings,
            object_refs,
            false,
        )
    })
    .or_else(|| {
        match resolve_form_owner_scoped_bound_data_path(
            &extended,
            attribute_metadata_owners_by_id,
            owner_scoped_bindings,
            object_refs,
        ) {
            FormOwnerScopedDataPath::Resolved(data_path) => Some(data_path),
            FormOwnerScopedDataPath::Unknown | FormOwnerScopedDataPath::Ambiguous => None,
        }
    })
    .or_else(|| {
        resolve_form_item_rooted_settings_composer_path(
            &extended,
            table_name_by_id,
            owner_scoped_bindings,
        )
    })
    .or_else(|| {
        resolve_form_item_rooted_chain_data_path(
            &extended,
            table_name_by_id,
            owner_scoped_bindings,
            object_refs,
        )
    })
}

#[allow(clippy::too_many_arguments)]
pub(super) fn parse_form_table_row_picture_data_path(
    schema: FormTableSchema,
    fields: &[&str],
    data_path: Option<&str>,
    attribute_names_by_id: &BTreeMap<String, String>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let table_name = data_path?;
    let encoded =
        split_1c_braced_fields(fields.get(schema.row_picture_data_path_slot())?.trim(), 0)?;
    let payload = match schema.row_picture_data_path(&encoded)? {
        FormTableRowPictureDataPath::Empty => return None,
        FormTableRowPictureDataPath::Payload(payload) => payload,
    };
    let payload = split_1c_braced_fields(payload, 0)?;
    let column_name = match payload.as_slice() {
        [column_id, uuid]
            if uuid
                .trim()
                .eq_ignore_ascii_case(FORM_VALUE_TABLE_COLUMN_BINDING_UUID) =>
        {
            let binding = fields.get(schema.data_path_slot())?.trim();
            return resolve_form_table_row_picture_member(
                binding,
                &format!("{{{},{}}}", column_id.trim(), uuid.trim()),
                attribute_names_by_id,
                attribute_metadata_owners_by_id,
                table_name_by_id,
                owner_scoped_bindings,
                object_refs,
            );
        }
        [column_id] if column_id.trim() == "10000000" => {
            let hidden =
                parse_exact_form_attribute_binding_id(fields.get(schema.data_path_slot())?.trim())
                    .and_then(|attribute_id| attribute_metadata_owners_by_id.get(&attribute_id))
                    .is_some_and(form_dynamic_list_default_picture_is_out_of_main_table);
            let prefix = if hidden && !table_name.starts_with('~') {
                "~"
            } else {
                ""
            };
            return Some(format!("{prefix}{table_name}.DefaultPicture"));
        }
        [column_id] if column_id.trim().parse::<u64>().is_ok() => {
            let binding = fields.get(schema.data_path_slot())?.trim();
            let Some(table_id) = parse_exact_form_attribute_binding_id(binding) else {
                // The table's binding is a chain, not a bare attribute, so the
                // member it names is read by the same walkers the data path
                // slot reads the chain with -- one segment longer.
                return resolve_form_table_row_picture_member(
                    binding,
                    &format!("{{{}}}", column_id.trim()),
                    attribute_names_by_id,
                    attribute_metadata_owners_by_id,
                    table_name_by_id,
                    owner_scoped_bindings,
                    object_refs,
                );
            };
            let Some(column_name) = table_column_names_by_id
                .get(&table_id)
                .and_then(|columns| columns.get(column_id.trim()))
                .map(String::as_str)
            else {
                // The row-picture index carries only the collection's own
                // picture column, and the slot may name any member the chain
                // walker can reach -- `Check` of a value list, for one.
                return resolve_form_table_row_picture_member(
                    binding,
                    &format!("{{{}}}", column_id.trim()),
                    attribute_names_by_id,
                    attribute_metadata_owners_by_id,
                    table_name_by_id,
                    owner_scoped_bindings,
                    object_refs,
                );
            };
            // The row picture reads the same field a data path reads, so the
            // list's own `~` marker applies here too. Evidence: UT 11.5.27.75
            // `DataProcessors/УправлениеВыгрузкамиВБидзаар/Forms/СписокПодключенийКСервису`,
            // Table `СписокПодключений` is written
            // `~СписокПодключений.НеОбновлятьДанныеТорговойПлощадки`.
            if !table_name.starts_with('~')
                && owner_scoped_bindings
                    .unresolvable_columns
                    .contains(&FormAttributeColumnKey {
                        attribute_id: table_id,
                        column_id: column_id.trim().to_string(),
                    })
            {
                let column_name = normalize_form_table_column_name(table_name, column_name);
                return Some(format!("~{table_name}.{column_name}"));
            }
            column_name
        }
        [kind, uuid] if matches!(kind.trim(), "0" | "4") => {
            let uuid = parse_non_zero_uuid(uuid.trim())?;
            let reference = object_refs.get(&uuid)?;
            form_metadata_attribute_suffix(reference)?
        }
        _ => return None,
    };
    let column_name = normalize_form_table_column_name(table_name, column_name);
    Some(format!("{table_name}.{column_name}"))
}

/// A bound chain `{K,s1,…,sK}` with one more segment appended, so that a slot
/// which names a member of what another slot's chain reached can be spelled by
/// the one chain walker rather than by a parallel resolver.
pub(super) fn form_bound_chain_with_extra_segment(chain: &str, segment: &str) -> Option<String> {
    let members = split_1c_braced_fields(chain.trim(), 0)?;
    let count = members.first()?.trim().parse::<usize>().ok()?;
    if members.len() != count + 1 {
        return None;
    }
    let mut out = format!("{{{}", count + 1);
    for member in &members[1..] {
        out.push(',');
        out.push_str(member.trim());
    }
    out.push(',');
    out.push_str(segment);
    out.push('}');
    Some(out)
}

fn form_metadata_attribute_suffix(reference: &str) -> Option<&str> {
    let mut parts = reference.rsplit('.');
    let name = parts.next()?;
    let kind = parts.next()?;
    (kind == "Attribute" && !name.is_empty()).then_some(name)
}

pub(super) fn normalize_form_table_column_name(table_name: &str, field_name: &str) -> String {
    let field_name = [Some(table_name), table_name.rsplit('.').next()]
        .into_iter()
        .flatten()
        .find_map(|prefix| {
            field_name.strip_prefix(prefix).filter(|suffix| {
                suffix
                    .chars()
                    .next()
                    .is_some_and(|first| !first.is_lowercase())
            })
        })
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| field_name.to_string());
    normalize_form_data_path_child_name(table_name, &field_name)
}

pub(super) fn normalize_form_data_path_child_name(parent_path: &str, name: &str) -> String {
    if form_data_path_uses_standard_property_names(parent_path) {
        normalize_form_standard_data_path_name(name)
    } else {
        name.to_string()
    }
}

pub(super) fn form_data_path_uses_standard_property_names(path: &str) -> bool {
    matches!(path.split('.').next().unwrap_or(path), "Объект" | "Запись")
}

pub(super) fn normalize_form_standard_data_path_name(name: &str) -> String {
    FORM_STANDARD_DATA_PATH_NAME_ALIASES
        .iter()
        .find_map(|(source, target)| (*source == name).then_some((*target).to_string()))
        .unwrap_or_else(|| name.to_string())
}

fn form_table_uuid_binding_key(binding_key: &str) -> Option<&str> {
    let (kind, uuid_text) = binding_key.split_once('|')?;
    let kind_number = kind.parse::<u64>().ok()?;
    if kind != kind_number.to_string() || uuid_text.contains('|') {
        return None;
    }
    let uuid = Uuid::parse_str(uuid_text).ok()?;
    (!uuid.is_nil() && uuid.to_string() == uuid_text).then_some(binding_key)
}

pub(super) fn parse_form_binding_key(field: &str) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let first = fields.first()?.trim();
    match fields.len() {
        1 => Some(first.to_string()),
        2 => Some(format!("{}|{}", first, fields.get(1)?.trim())),
        _ => None,
    }
}

pub(super) fn parse_form_bound_data_binding_key(field: &str) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    match fields.first().map(|value| value.trim()) {
        Some("2") => parse_form_binding_key(fields.get(2)?.trim()),
        Some("3") => parse_form_binding_key(fields.get(3)?.trim()),
        _ => None,
    }
}

pub(super) fn parse_form_bound_attribute_id(field: &str) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    match fields.first().map(|value| value.trim()) {
        Some("2") | Some("3") => split_1c_braced_fields(fields.get(1)?.trim(), 0)?
            .first()
            .map(|value| value.trim().to_string()),
        _ => None,
    }
}

pub(super) fn infer_form_bound_property_name(names: &BTreeSet<String>) -> Option<String> {
    let mut iter = names.iter();
    let first = iter.next()?.as_str();
    let mut prefix = first.to_string();
    for name in iter {
        prefix = common_prefix(&prefix, name);
        if prefix.is_empty() {
            break;
        }
    }
    if prefix.is_empty() {
        names.iter().min_by_key(|name| name.len()).cloned()
    } else {
        Some(prefix)
    }
}

pub(super) fn common_prefix(left: &str, right: &str) -> String {
    left.chars()
        .zip(right.chars())
        .take_while(|(left, right)| left == right)
        .map(|(ch, _)| ch)
        .collect()
}

pub(super) fn parse_form_table_binding(field: &str) -> Option<(String, String)> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first().map(|field| field.trim()) != Some("2") {
        return None;
    }
    let attribute_id = split_1c_braced_fields(fields.get(1)?.trim(), 0)?
        .first()?
        .trim()
        .to_string();
    let table_key = parse_form_binding_key(fields.get(2)?.trim())?;
    Some((attribute_id, table_key))
}

pub(super) fn parse_form_nested_table_column_binding(
    field: &str,
) -> Option<(String, String, String)> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first().map(|value| value.trim()) != Some("3") {
        return None;
    }
    let attribute_id = split_1c_braced_fields(fields.get(1)?.trim(), 0)?
        .first()?
        .trim()
        .to_string();
    let table_key = parse_form_binding_key(fields.get(2)?.trim())?;
    let column_key = parse_form_binding_key(fields.get(3)?.trim())?;
    Some((attribute_id, table_key, column_key))
}

pub(super) fn parse_form_direct_table_column_binding(field: &str) -> Option<(String, String)> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first()?.trim().parse::<u8>().ok()? != 2 || fields.len() != 3 {
        return None;
    }
    let owner = split_1c_braced_fields(fields.get(1)?.trim(), 0)?;
    if owner.len() != 1 {
        return None;
    }
    let attribute_id = owner.first()?.trim();
    if attribute_id.is_empty() {
        return None;
    }
    let column_key = parse_form_binding_key(fields.get(2)?.trim())?;
    let column_id = column_key.parse::<u64>().ok()?;
    if column_id == 0 || column_id.to_string() != column_key {
        return None;
    }
    Some((attribute_id.to_string(), column_key))
}

pub(super) fn form_child_item_binding_fields<'a>(tag: &str, fields: &'a [&'a str]) -> Vec<&'a str> {
    let input_field_offset = matches!(
        tag,
        "InputField"
            | "LabelField"
            | "CheckBoxField"
            | "PictureField"
            | "RadioButtonField"
            | "TextDocumentField"
            | "CalendarField"
            | "GraphicalSchemaField"
            | "SpreadSheetDocumentField"
            | "HTMLDocumentField"
    )
    .then(|| {
        form_input_field_layout_is_extended(fields)
            .then(|| form_input_field_top_level_offset(fields))
    })
    .flatten()
    .unwrap_or(0);
    match tag {
        "Table" => fields.get(11).copied().into_iter().collect(),
        "InputField"
        | "LabelField"
        | "CheckBoxField"
        | "PictureField"
        | "RadioButtonField"
        | "TextDocumentField"
        | "CalendarField"
        | "GraphicalSchemaField"
        | "SpreadSheetDocumentField"
        | "HTMLDocumentField" => [11usize, 12]
            .iter()
            .filter_map(|index| fields.get(*index + input_field_offset).copied())
            .collect(),
        _ => Vec::new(),
    }
}

pub(super) fn parse_form_attribute_binding_id(field: &str) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first().map(|field| field.trim()) != Some("1") {
        return None;
    }
    let ids = split_1c_braced_fields(fields.get(1)?.trim(), 0)?;
    Some(ids.first()?.trim().to_string())
}

pub(super) fn parse_form_attribute_data_path(
    field: &str,
    name: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first().map(|field| field.trim()) != Some("1") {
        return None;
    }
    let ids = split_1c_braced_fields(fields.get(1)?.trim(), 0)?;
    let attribute_id = ids.first()?.trim();
    attribute_names_by_id
        .get(attribute_id)
        .cloned()
        .or_else(|| Some(name.to_string()))
}

pub(super) fn parse_form_button_command_name(
    field: &str,
    commands: &[FormCommand],
    object_refs: &BTreeMap<String, String>,
    standard_command_owner_name_by_id: &BTreeMap<String, FormStandardCommandOwner>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let kind = fields.first()?.trim();
    if fields.len() == 1 && kind == "0" {
        return Some("0".to_string());
    }
    let uuid = parse_non_zero_uuid(fields.get(1)?.trim())?;
    if kind == "0" {
        if let Some(command_name) =
            form_standard_button_command_name(&uuid).or_else(|| form_standard_command_name(&uuid))
        {
            return Some(command_name.to_owned());
        }
        if let Some(command_name) = object_refs.get(&uuid) {
            return Some(form_object_reference_command_name(command_name));
        }
        return None;
    }
    if let Some(command_name) = commands
        .iter()
        .find(|command| command.id == kind && command.reference_uuid == uuid)
        .map(|command| format!("Form.Command.{}", command.name))
    {
        return Some(command_name);
    }
    if kind == "100"
        && let Some(reference) = object_refs.get(&uuid)
        && reference.starts_with("CommonForm.")
    {
        return Some(form_object_reference_command_name(reference));
    }
    // An item owner claims the record before any family rule does: `kind` is an
    // item id far more often than a family selector, and the two are told apart
    // by whether the uuid resolves as that owner's standard command.  A button
    // record whose `kind` is 1 resolves to `Form.Item.Товары.…GetURL` under a
    // table owner and to `Catalog.СезонныеГруппы.…Create` under the family rule,
    // from the very same `kind`.
    if let Some(owner) = standard_command_owner_name_by_id.get(kind)
        && let Some(standard) = match owner.kind {
            FormStandardCommandOwnerKind::FormattedDocument => {
                form_formatted_document_standard_command_suffix(&uuid)
            }
            FormStandardCommandOwnerKind::PdfDocument => {
                form_pdf_document_standard_command_suffix(&uuid)
            }
            FormStandardCommandOwnerKind::GraphicalSchema => {
                form_graphical_schema_standard_command_suffix(&uuid)
            }
            FormStandardCommandOwnerKind::SpreadsheetDocument => {
                form_spreadsheet_document_standard_command_suffix(&uuid)
            }
            FormStandardCommandOwnerKind::Table => form_table_standard_command_suffix(&uuid),
        }
    {
        return Some(format!(
            "Form.Item.{}.StandardCommand.{standard}",
            owner.name
        ));
    }
    let reference = object_refs.get(&uuid)?;
    form_object_family_standard_command_name(kind, reference, FormCommandRecordReader::Button)
}

/// Which of the two places a `{kind, uuid}` command record was read from.
///
/// The two readers agree on every row of the family grammar but one, and that one
/// is named rather than duplicated, so the tables cannot drift apart again.
#[derive(Clone, Copy, Eq, PartialEq)]
enum FormCommandRecordReader {
    /// A `<Button>`'s command slot.
    Button,
    /// A command-interface item, i.e. a navigation-panel or command-bar entry.
    CommandInterfaceItem,
}

/// Standard command a `{kind, uuid}` record names when `kind` selects a family of
/// the *target metadata object* rather than a form command or a form item owner.
///
/// The record carries nothing but the kind and the uuid, so the family of the
/// object the uuid resolves to is what decides the suffix -- the same shape
/// `e712d9a` established for the command-interface reader.  Both readers of the
/// record now decode this half through one function, so the two cannot drift
/// apart again: they were already disagreeing, the button reader knowing only
/// slot 4 while the command-interface reader knew slots 1 through 5.
///
/// Every arm is a total function on its observed set in the corpus-wide button
/// join (27 773 records, 0 wrong, 0 unjoinable):
///   * slot 1, a catalog -- `Create` for a button, on its 1 observation, and
///     nothing for a command-interface item, which is a negative an earlier
///     package measured for that reader and this corpus offers nothing to
///     overturn.  One datum does not generalise across readers, so the row
///     names the reader instead of being copied into two tables;
///   * slot 1, a register -- `OpenByRecorder`, the command-interface rule;
///   * slot 2 -- `CreateBasedOn` on 21 records spanning `Document` (18),
///     `BusinessProcess` (2) and `ExchangePlan` (1), and `OpenByRecorder` for an
///     information register, which is the exception `e712d9a` measured;
///   * slot 3, a catalog -- `CreateBasedOn`;
///   * slot 4, a catalog -- `OpenByValue`.
///
/// An unobserved combination returns `None` rather than a guessed name.
///
/// Whether a top-level reference is required is stated per slot, exactly as each
/// of the two readers already required it before they were joined: slot 2 names
/// `CreateBasedOn` for any reference it is given, and only the slots that were
/// already restricted stay restricted.  Tightening a guard that no observation
/// asks for is how this series has lost 48 native groups before.
fn form_object_family_standard_command_name(
    kind: &str,
    reference: &str,
    reader: FormCommandRecordReader,
) -> Option<String> {
    let top_level = |expected: &str| is_top_level_reference_of_kind(reference, expected);
    let top_level_register = || {
        matches!(
            reference.split_once('.').map(|(head, _)| head),
            Some(
                "AccountingRegister"
                    | "AccumulationRegister"
                    | "CalculationRegister"
                    | "InformationRegister"
            )
        ) && reference.matches('.').count() == 1
    };
    let standard = match kind {
        "1" if top_level("Catalog") => match reader {
            FormCommandRecordReader::Button => "Create",
            FormCommandRecordReader::CommandInterfaceItem => return None,
        },
        "1" if top_level_register() => "OpenByRecorder",
        "2" if top_level("InformationRegister") => "OpenByRecorder",
        "2" => "CreateBasedOn",
        "3" if top_level("Catalog") => "CreateBasedOn",
        "4" if top_level("Catalog") => "OpenByValue",
        _ => return None,
    };
    Some(format!("{reference}.StandardCommand.{standard}"))
}

/// Whether `uuid` -- already resolved to a metadata object reference by the
/// caller -- has standard commands at all
/// (`MetadataCommandReference::use_standard_commands`). A uuid absent from the
/// index (every kind but `Catalog`, today) is treated as enabled, matching
/// every reader's behaviour before this index existed.
///
/// This is a distinct question from "does the family table have a rule for
/// this particular kind against this particular reference": `false` here
/// means the target has *no* standard command, so nothing --
/// `form_object_family_standard_command_name` included -- can ever resolve
/// through it and the caller must fall back to the raw sentinel outright,
/// without asking the family table at all. A family-table miss on an
/// *enabled* target is a different, already-proven negative (e.g. a catalog
/// asked for kind `1`'s command-interface reading, which the family table
/// answers `None` for on 27 773 evidenced button records, none of them
/// naming a disabled catalog) and must keep falling through to `None`
/// (dropping the item, not a sentinel) exactly as before this index existed.
///
/// Evidence: ERP UH MDM_Management `Catalog.СправочникиБД`
/// (`UseStandardCommands=false`) is target `4:67b8886f-f30d-480c-abb8-e3712f3c169c`
/// in `Catalogs/ТипыБазДанных/Forms/ФормаЭлемента/Ext/Form.xml`'s
/// `<NavigationPanel>`; the platform keeps the raw sentinel rather than
/// writing `Catalog.СправочникиБД.StandardCommand.OpenByValue`, the name
/// `form_object_family_standard_command_name` would otherwise construct for
/// kind `4` unconditionally.
fn form_command_interface_target_use_standard_commands(
    uuid: &str,
    context: &FormCommandInterfaceParseContext<'_>,
) -> bool {
    context
        .metadata_command_refs
        .get(uuid)
        .is_none_or(|metadata| metadata.use_standard_commands)
}

