fn format_form_spreadsheet_document_properties_xml(item: &FormChildItem, indent: usize) -> String {
    let Some(properties) = item.spreadsheet_document_properties.as_ref() else {
        return String::new();
    };
    let tab = "\t".repeat(indent);
    let mut xml = String::new();
    if properties.show_grid == Some(true) {
        xml.push_str(&format!("{tab}<ShowGrid>true</ShowGrid>\r\n"));
    }
    if properties.show_headers == Some(true) {
        xml.push_str(&format!("{tab}<ShowHeaders>true</ShowHeaders>\r\n"));
    }
    if properties.show_cell_names == Some(true) {
        xml.push_str(&format!("{tab}<ShowCellNames>true</ShowCellNames>\r\n"));
    }
    if properties.show_row_and_column_names == Some(true) {
        xml.push_str(&format!(
            "{tab}<ShowRowAndColumnNames>true</ShowRowAndColumnNames>\r\n"
        ));
    }
    if let Some(value) = properties.vertical_scroll_bar {
        xml.push_str(&format!(
            "{tab}<VerticalScrollBar>{}</VerticalScrollBar>\r\n",
            xml_bool(value)
        ));
    }
    if let Some(value) = properties.horizontal_scroll_bar {
        xml.push_str(&format!(
            "{tab}<HorizontalScrollBar>{}</HorizontalScrollBar>\r\n",
            xml_bool(value)
        ));
    }
    if properties.edit == Some(true) {
        xml.push_str(&format!("{tab}<Edit>true</Edit>\r\n"));
    }
    // `Protection` leads `SelectionShowMode` (8) and `Output` (1) and trails
    // `HorizontalScrollBar` (21), `VerticalScrollBar` (9), `CommandSet` (4)
    // and `ShowGrid` (1) on the 26 native fields that carry it; it never
    // shares a field with `Edit`, so it stays behind it.  It used to trail
    // `Output`.
    if properties.protection == Some(true) {
        xml.push_str(&format!("{tab}<Protection>true</Protection>\r\n"));
    }
    if let Some(value) = properties.selection_show_mode {
        xml.push_str(&format!(
            "{tab}<SelectionShowMode>{}</SelectionShowMode>\r\n",
            escape_xml_text(value)
        ));
    }
    if let Some(value) = properties.output {
        xml.push_str(&format!(
            "{tab}<Output>{}</Output>\r\n",
            escape_xml_text(value)
        ));
    }
    // `ShowGroups` leads the drag pair, it does not trail it: on the three of
    // the four native fields that carry it together with the pair,
    // `<ShowGroups>false</ShowGroups>` stands between `SelectionShowMode` and
    // `EnableStartDrag`, and on the fourth -- which has no pair --
    // `SelectionShowMode` still precedes it.  It never shares a field with
    // `Output`, so the two are not ordered against each other by observation.
    if properties.show_groups == Some(false) {
        xml.push_str(&format!("{tab}<ShowGroups>false</ShowGroups>\r\n"));
    }
    if properties.enable_start_drag == Some(false) {
        xml.push_str(&format!(
            "{tab}<EnableStartDrag>false</EnableStartDrag>\r\n"
        ));
    }
    if properties.enable_drag == Some(false) {
        xml.push_str(&format!("{tab}<EnableDrag>false</EnableDrag>\r\n"));
    }
    // `ViewScalingMode` closes the spreadsheet field's own scalar run: on all
    // 40 native fields that carry it, it trails `TitleLocation` (40),
    // `DataPath` (40), `HorizontalScrollBar` (33), `Width` (32),
    // `HorizontalStretch` (29), `Height` (25), `MaxHeight` (23), `MaxWidth`
    // (12), `VerticalScrollBar` (11) and `Protection` (11) and leads only
    // `ExtendedTooltip` (40), `ContextMenu` (40) and `Events` (15); it never
    // shares a field with `SelectionShowMode`, `Output` or the drag pair.
    if let Some(value) = properties.view_scaling_mode {
        xml.push_str(&format!(
            "{tab}<ViewScalingMode>{}</ViewScalingMode>\r\n",
            escape_xml_text(value)
        ));
    }
    // `DrawingSelectionShowMode` closes the same run: the one native field
    // that carries it puts it behind `DataPath` and `TitleLocation` and ahead
    // of `ContextMenu`, `ExtendedTooltip` and `Events`.  It never shares a
    // field with `ShowGroups`, so their relative order is unobserved.
    if let Some(value) = properties.drawing_selection_show_mode {
        xml.push_str(&format!(
            "{tab}<DrawingSelectionShowMode>{}</DrawingSelectionShowMode>\r\n",
            escape_xml_text(value)
        ));
    }
    xml
}

fn format_form_table_properties_xml(item: &FormChildItem, indent: usize) -> String {
    if item.tag != "Table" {
        return String::new();
    }
    let mut xml = String::new();
    for property in FORM_TABLE_XML_ORDER {
        xml.push_str(&format_form_table_property_xml(item, *property, indent));
    }
    xml
}

