    // with the title block, ahead of every one of those six.
    if item.tag == "ColumnGroup"
        && let Some(fixing_in_table) = item.fixing_in_table
    {
        xml.push_str(&format!(
            "{tab}\t<FixingInTable>{}</FixingInTable>\r\n",
            fixing_in_table.xml_value()
        ));
    }
    // `UsualGroup`, `InputField` and `Page` each write `Format` from their own
    // property order, at the place their own native items put it.
    if !matches!(item.tag, "UsualGroup" | "InputField" | "Page") && !item.format.is_empty() {
        xml.push_str(&format_form_localized_section(
            "Format",
            &item.format,
            indent + 1,
        ));
    }
    if item.tag != "InputField" && !item.edit_format.is_empty() {
        xml.push_str(&format_form_localized_section(
            "EditFormat",
            &item.edit_format,
            indent + 1,
        ));
    }
    // `EqualItemsWidth` closes the check box body, behind `CheckBoxType` (3 of
    // the 3 native check boxes that carry it) and `EditFormat` (2), and ahead
    // of `ContextMenu`, `ExtendedTooltip` and `Events`; nothing else shares a
    // check box with it.
    if let Some(equal_items_width) = item.equal_items_width {
        xml.push_str(&format!(
            "{tab}\t<EqualItemsWidth>{}</EqualItemsWidth>\r\n",
            xml_bool(equal_items_width)
        ));
    }
    // A `LabelField` closes with `Hiperlink`, `Border`, `BorderColor`,
    // `TextColor`, `BackColor`, `Font`, in that order.  UT 11.5.27.75 native
